window.JASTROW_CHUNKS[1010]={"36512":{"h":"דְּקָקָה","r":"KRU05463","alt":[],"source":"krupnik","glosses":[{"text":"a tender child","label":""}],"html":"<p>תינוק a tender child  ירוש׳ ר״ה ב׳ כ״ח ע״ב: כהדא דקקה.</p>","notation":["נ׳"]},"36513":{"h":"דֶּקֶר","r":"KRU05464","alt":["דִּקְרָא"],"source":"krupnik","glosses":[{"text":"mattock","label":""}],"html":"<p>כלי לחפור בו בקרקע mattock  ביצה פ״א מ״ב: יחפור בדקר; פסח׳ קי״א ע״ב: דקרי דפרזלא.</p>","notation":[]},"36514":{"h":"דַּקְתָּא","r":"KRU05467","alt":[],"source":"krupnik","glosses":[{"text":"oakum","label":""}],"html":"<p>נעורת oakum  חול׳ נ״א ע״ב: דקתא.</p>","notation":["נ׳"]},"36515":{"h":"דָּר","r":"KRU05469","alt":["דָּרָא"],"source":"krupnik","glosses":[{"text":"generation","label":"1"},{"text":"row","label":"2"},{"text":"pyre","label":"3"}],"html":"<p>1 דור generation  כתוב׳ י״ז ע״א: חד בדרא.\n2 שורה row  ב״ר פ״כ: שהיא עשויה דרין דרין; כתוב׳ ס׳ ע״א: אותבה בדרא דנשי.\n3 מדורה pyre  שהש״ר ג׳ ד׳: דרא יקידא יקדת.</p>","notation":[]},"36516":{"h":"דָּרָא","r":"KRU05470","alt":[],"source":"krupnik","glosses":[{"text":"a precious stone","label":""}],"html":"<p>מין אבן טובה a precious stone  מגי׳ י״ד ע״א: אבן טובה יש בכרכי הים ודרא שמה.</p>","notation":["ז׳"]},"36517":{"h":"דָּרָא²","r":"KRU05471","alt":[],"source":"krupnik","glosses":[{"text":"court","label":"1"},{"text":"damp","label":"2"}],"html":"<p>1  court  תרג׳ אסת׳ ו׳ ה׳ (והמן עומד בחצר): המן קאים בדרא.\n2  damp  פסח׳ כ״ו ע״א: אסא דרא.</p>","notation":[]},"36518":{"h":"דְּרָא","r":"KRU05472","alt":[],"source":"krupnik","glosses":[{"text":"to carry","label":"1"},{"text":"to winnow, to scatter","label":"2"}],"html":"<p>1 נשא to carry  חול׳ ק״ה ע״ב: שקולאי דדרו חביתא.\n2 זרה to winnow, to scatter  ב״מ ע״ד ע״א: מידם ומידרא; תרג׳ יב״ע ויקר׳ כ״ו ל״ב: ויתכון אדרי ביני עממיא.</p>","notation":["פ״י"]},"36519":{"h":"דְּרָאזָא","r":"KRU05473","alt":[],"source":"krupnik","glosses":[{"text":"hard","label":""}],"html":"<p>קשה hard  שבת קנ״ה ע״א: זירין דראזי.</p>","notation":["ת׳"]},"36520":{"h":"דָּרְבָּאן","r":"KRU05475","alt":["דָּרְבּוֹן"],"source":"krupnik","glosses":[{"text":"guardsman","label":""}],"html":"<p>שומר guardsman  בכורות ח׳ ע״ב: אשכח דרבאני מגואי ודרבאני מבראי; דב״ר פ״ו: בא הדרבון וישב לו כנגדה.</p>","notation":[]},"36521":{"h":"דַּרְבָּן","r":"KRU05476","alt":[],"source":"krupnik","glosses":[{"text":"door","label":""}],"html":"<p>פתח door  תוספ׳ כל׳ ב״מ ו׳: דרבן הכרם.</p>","notation":["ז׳"]},"36522":{"h":"דרג","r":"KRU05477","alt":[],"source":"krupnik","glosses":[{"text":"to make appear like steps","label":"הפ׳,"}],"html":"<p>הפ׳, הִדְרִיג עשה כעין מדרגה to make appear like steps  ירוש׳ שביע׳ פ״ד ל״ה ע״ב: מחליק ומדריג.</p>","notation":["Source marks no qal form"]},"36523":{"h":"דַּרְגָּא","r":"KRU05478","alt":[],"source":"krupnik","glosses":[{"text":"step","label":"1"},{"text":"pace","label":"2"}],"html":"<p>1 מדרגה step  ירוש׳ קיד׳ ד׳ ס״ו ע״א: נחית דרגא נסיב אתתא סק דרגא בחר שושבינא.\n2 פסיעה pace  תרג׳ ש״ב ו׳ י״ג (ששה צעדים): שתא דרגין.</p>","notation":["ז׳"]},"36524":{"h":"דַּרְגּוֹן","r":"KRU05479","alt":[],"source":"krupnik","glosses":[{"text":"staff, suite","label":""}],"html":"<p>בני לויה staff, suite  במד״ר פ״ד: קדשן שיהיו עושין דרגון לפניו.</p>","notation":["ז׳"]},"36525":{"h":"דרגי","r":"KRU05481","alt":["דרגיבת"],"source":"krupnik","glosses":[{"text":"a charm formula","label":""}],"html":"<p>מין לחש a charm formula  ירוש׳ שבת פ״ו ח׳ ע״ג: דרגי דרגיבת משום דרכי האמורי.</p>","notation":[]},"36526":{"h":"דַּרְגָּשׁ","r":"KRU05482","alt":["דַּרְגָּשָׁא"],"source":"krupnik","glosses":[{"text":"couch","label":""}],"html":"<p>מין מטה couch  נדר׳ פ״ז מ״ד: הנודר מן המטה מותר בדרגש דברי רבי מאיר וחכמים אומרים דרגש בכלל מטה; תרג׳ בראש׳ מ״ז ל״א (על ראש המטה): על ריש דרגשא.</p>","notation":[]},"36527":{"h":"דרד","r":"KRU05483","alt":[],"source":"krupnik","glosses":[{"text":"to roll down","label":"התפ׳,"}],"html":"<p>התפ׳, הִדַּרֵד נתגלגל ונפל to roll down  שהש״ר ו׳ י״א: את נוטל אחד מהכרי וכולן מדרדין.</p>","notation":["Source marks no qal form"]},"36528":{"h":"דרד²","r":"KRU05484","alt":[],"source":"krupnik","glosses":[{"text":"to remove ashes","label":"דָּרֵד פַעל,"},{"text":"to glide down","label":"אִידְּרִיד אתפ׳,"}],"html":"<p>דָּרֵד פַעל, דישן to remove ashes  תרג׳ ירוש׳ במדבר׳ ד׳ י״ג: וידרדון ית מדבחא.\nאִידְּרִיד אתפ׳, נשמט to glide down  סוט׳ מ״ד ע״א: מידריד ונפל.</p>","notation":["Source marks no qal form"]},"36529":{"h":"דַּרְדֵּג","r":"KRU05485","alt":[],"source":"krupnik","glosses":[{"text":"to drip","label":""}],"html":"<p>טפטף to drip  כתוב׳ י״ז ע״א: דרדיג משחא ארישא.</p>","notation":["פ״י"]},"36530":{"h":"דַּרְדּוּר","r":"KRU05486","alt":[],"source":"krupnik","glosses":[{"text":"barrel","label":"1"},{"text":"a head-covering","label":"2"}],"html":"<p>1 חבית barrel  כלים פט״ו מ״א: דרדור עגלה.\n2 מין כיסוי ראש a head-covering  ספרי בשלח קט״ו: הדרדור של אשה.</p>","notation":["ז׳"]},"36531":{"h":"דַּרְדַּנְיָא","r":"KRU05488","alt":["דַּרְדַּנְיָיא"],"source":"krupnik","glosses":[{"text":"Dardania, a district in Asia Minor","label":""}],"html":"<p>Dardania, a district in Asia Minor  ב״ר ל״ז: דדנים – דרדניא; ירוש׳ מגיל׳ פ״א מ״ז ע״ב: דרדנייה. </p>","notation":[]},"36532":{"h":"דַּרְדְּסִין","r":"KRU05489","alt":[],"source":"krupnik","glosses":[{"text":"socks","label":""}],"html":"<p>מין פוזמקאות socks  ירוש׳ כלא׳ פ״ט ל״ב ע״ד: דרדסין דכיתן דרדסין דעמר.</p>","notation":["ז״ר"]},"36533":{"h":"דַּרְדָּק","r":"KRU05490","alt":["דַּרְדְּקָא"],"source":"krupnik","glosses":[{"text":"small, young","label":""}],"html":"<p>קטן small, young  תרג׳ איוב ג׳ י״ט: יעקב דאתקרי דרדק; ב״ב כ״א ע״א: מקרי דרדקי.</p>","notation":[]},"36534":{"h":"דרדר","r":"KRU05491","alt":[],"source":"krupnik","glosses":[{"text":"to roll down","label":"התפ׳,"}],"html":"<p>התפ׳, הִדַּרְדֵּר נתגלגל ונפל to roll down  שהש״ר ו׳ י״א: את נוטל אחד מהכרי וכולן מידרדרין.</p>","notation":["Source marks no qal form"]},"36535":{"h":"דַּרְדָּרָא","r":"KRU05492","alt":[],"source":"krupnik","glosses":[{"text":"thistle","label":""}],"html":"<p>מין קוצים thistle  גיט׳ ע׳ ע״א: דרדרא – מוריקא דחוחא.</p>","notation":["ז׳"]},"36536":{"h":"דְּרוּכוֹת","r":"KRU05493","alt":[],"source":"krupnik","glosses":[{"text":"grape or olive treaders","label":""}],"html":"<p>דורכים בגתות grape or olive treaders  ירוש׳ תרומ׳ פ״ג מ״ב ע״א: הדרוכות מכיון שהילכו וכו׳.</p>","notation":["ז״ר"]},"36537":{"h":"דְּרוֹלְמוֹסְיָא","r":"KRU05495","alt":[],"source":"krupnik","glosses":[{"text":"punishment","label":""}],"html":"<p>עונש punishment  ב״ר פל״ב: שקבע דרולמוסיא שלו במדינה.</p>","notation":["נ׳"]},"36538":{"h":"דָּרוֹם","r":"KRU05496","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Palestine","label":""}],"html":"<p>שם מקום בארץ ישראל name of a place in Palestine  יבמ׳ מ״ה ע״א: זקני דרום.</p>","notation":["Marked biblical in source"]},"36539":{"h":"דָּרוֹמָא","r":"KRU05497","alt":[],"source":"krupnik","glosses":[{"text":"South","label":"2"}],"html":"<p>1 כנ״ל. ויקר״ר: רבנין דרומא. \n2 נגב South  תרג׳ דבר׳ ל״ד ג׳ (ואת הנגב): וית דרומא.</p>","notation":["ז׳"]},"36540":{"h":"דְּרוֹמוֹס","r":"KRU05499","alt":[],"source":"krupnik","glosses":[{"text":"race-course","label":""}],"html":"<p>מקום מרוץ race-course  קיד׳ ס״ג ע״א: עשה לפני כדרומוס הזה.</p>","notation":["ז׳"]},"36541":{"h":"דְּרוֹמִי","r":"KRU05500","alt":[],"source":"krupnik","glosses":[{"text":"southern","label":""}],"html":"<p>מצד דרום southern  ב״ב כ״ה ע״ב: רוח דרומית.</p>","notation":["ת׳"]},"36542":{"h":"דְּרוֹמְנָה","r":"KRU05502","alt":[],"source":"krupnik","glosses":[{"text":"of Daroma","label":""}],"html":"<p>מן העיר דרומא of Daroma  ירוש׳ ברכ׳ פ״א ב׳ ע״ב: ר׳ יעקב דרומנה.</p>","notation":["ז׳"]},"36543":{"h":"דְּרוֹסָא","r":"KRU05504","alt":["דְּרוֹסַאי"],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ יומא פ״ד מ״א ע״ד: ר׳ דרוסא; במ״ר י״ב: דרוסאי.</p>","notation":[]},"36544":{"h":"דָּרוֹסָה","r":"KRU05505","alt":[],"source":"krupnik","glosses":[{"text":"name of a coin","label":""}],"html":"<p>מין מטבע name of a coin  ירוש׳ קיד׳ פ״א נ״ח ע״ד: שלשה דורסים מעה שני ביצים דרוסה.</p>","notation":["ז׳"]},"36545":{"h":"דְּרוּסָה","r":"KRU05506","alt":[],"source":"krupnik","glosses":[{"text":"an animal attacked by a beast","label":"1"},{"text":"pomace of fruits","label":"2"}],"html":"<p>1 בהמה שנטרפה ע״י חיה an animal attacked by a beast  חול׳ פ״ג מ״א: דרוסת הזאב בדקה דרוסת הארי בגסה.\n2 פירות כבושים לגוש pomace of fruits  תוספ׳ מ״ש א׳: דרוסות תמרות.</p>","notation":["נ׳"]},"36546":{"h":"דְּרוּסַת אִישׁ","r":"KRU05507","alt":[],"source":"krupnik","glosses":[{"text":"defloured","label":""}],"html":"<p>בעולת איש defloured  כת׳ פ״א מ״ז: היא אומרת מוכת עץ אני והוא אומר לא כי דרוסת איש את.</p>","notation":[]},"36547":{"h":"דְּרוֹסָא²","r":"KRU05508","alt":["דְּרוֹסַי"],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  שהש״ר ג׳ י׳: דרוסה; במ״ר י״ב: ר׳ דרוסי.</p>","notation":[]},"36548":{"h":"דְּרוֹעָה","r":"KRU05509","alt":[],"source":"krupnik","glosses":[{"text":"arm","label":""}],"html":"<p>זרוע arm  ב״ר פ׳ ע״ח: גלה בה דרועא.</p>","notation":["ז׳"]},"36549":{"h":"דְּרוּפְתְּקָא","r":"KRU05510","alt":[],"source":"krupnik","glosses":[{"text":"receptacle","label":""}],"html":"<p>בית קבול receptacle  סנה׳ צ״ט ע״ב: כולהו גופי דרופתקי נינהו.</p>","notation":["ז׳"]},"36550":{"h":"דְּרוּקָא","r":"KRU05511","alt":[],"source":"krupnik","glosses":[{"text":"a troop of soldiers","label":""}],"html":"<p>גדוד צבא a troop of soldiers  כתוב׳ ס״ב ע״א: לא חליף דרוקא דמלכא אבביה.</p>","notation":["ז׳"]},"36551":{"h":"דְּרוּקְרָא","r":"KRU05512","alt":["דְּרוֹקֶרֶת"],"source":"krupnik","glosses":[{"text":"a Babylonian town","label":""}],"html":"<p>שם עיר בבבל a Babylonian town  תענ׳ כ״א ע״ב: דרוקרת עיר המוציאה חמש מאות רגלי; שבת צ״ב ע״ב: ההוא שכבא דהוה בדרוקרא.</p>","notation":[]},"36552":{"h":"דְּרוֹר","r":"KRU05513","alt":[],"source":"krupnik","glosses":[{"text":"jewel","label":""}],"html":"<p>תכשיט jewel  ירוש׳ סנה׳ פ״י כ״ח ע״א: כדרבונות – כדרור נאות.</p>","notation":["Marked biblical in source"]},"36553":{"h":"דָּרוֹשָׁא","r":"KRU05516","alt":[],"source":"krupnik","glosses":[{"text":"lecturer","label":""}],"html":"<p>דרשן lecturer  ירוש׳ סוט׳ פ״א ט״ז ע״ד: מישמע קליה דדרושא.</p>","notation":["ז׳"]},"36554":{"h":"דְּרֵי","r":"KRU05517","alt":[],"source":"krupnik","glosses":[{"text":"to carry, to bear","label":""},{"text":"to scatter, to winnow","label":""},{"text":"to jump up","label":""}],"html":"<p>1) נשא, סבל to carry, to bear  ע״ז ס׳ ע״א: דרי זיקא; שבת ע״ז ע״א: כל חמרא דלא דרי על חד תלתא מיא לאו חמרא. 2) תרג׳ יב״ע ויק׳ כ״ו ל״ג (ואתכם אזרה בגוים): ויתרון אדרי ביני עממיא; ב״מ ק״ה ע״א: אידוש ואידרי. to scatter, to winnow  אִידְּרִי אתפ׳, קפץ אל־ to jump up  ע״ז כ״ט ע״ב: אידרי נכרי. </p>","notation":["פ״י"]},"36555":{"h":"דְּרִיסָה","r":"KRU05520","alt":[],"source":"krupnik","glosses":[{"text":"walking, crossing","label":"1"},{"text":"treading","label":"2"}],"html":"<p>1 פסיעה walking, crossing  מגיל׳ ח׳ ע״א: דריסת הרגל.\n2 דריכה ורמיסה treading  שבת קמ״ה ע״א: דריסת זיתים.</p>","notation":["נ׳"]},"36556":{"h":"דְּרִישָׁה","r":"KRU05521","alt":[],"source":"krupnik","glosses":[{"text":"examination","label":"1"},{"text":"interpretation","label":"2"}],"html":"<p>1 חקירה examination  סנה׳ פ״ב מ״א: אחד דיני ממונות ואחד דיני נפשות בדרישה וחקירה.\n2 ביאור בדרך דרש interpretation  פסח׳ כ״ב ע״ב: כשם שקבלתי שכר על הדרישה.</p>","notation":["נ׳"]},"36557":{"h":"דָּרַךְ","r":"KRU05522","alt":[],"source":"krupnik","glosses":[{"text":"to be trodden","label":"נִדְרַךְ נפ׳,"}],"html":"<p>נִדְרַךְ נפ׳, נרמס to be trodden  תר׳ פ״א מ״ח: ענבים הנדרכות.</p>","notation":["Marked biblical in source"]},"36558":{"h":"דְּרַךְ","r":"KRU05523","alt":[],"source":"krupnik","glosses":[{"text":"to tread","label":""},{"text":"to go to and fro","label":""},{"text":"to thresh","label":""},{"text":"to lead","label":""},{"text":"to catch up","label":""}],"html":"<p>1) דרך ופסע to tread  שבת ק״ט ע״א: חזייא דדריכא ליה חמרא אגבא. 2) התהלך to go to and fro  ויק״ר פכ״ז: דרכת עד דחסל דיינא. אַדְרֵךְ אפ׳ 1) דש to thresh  תרג׳ ישעי׳ כ״ח כ״ז (יודש קצח): מדרכין קצחא. 2) הדריך to lead  תרג׳ תהל׳ כ״ה ה׳ (הדריכני באמתך): אדרך לי בקושטך. 3) השיג to catch up  ע״ז ט״ו ע״ב: רהיט בתריה וכו׳ ולא אדרכיה. </p>","notation":["פ״ע"]},"36559":{"h":"דֶּרֶךְ דֶּרֶךְ אֶרֶץ","r":"KRU05524","alt":[],"source":"krupnik","glosses":[{"text":"secular occupation, trade","label":"1"},{"text":"good manners","label":"2"},{"text":"euph. sexual connection","label":"3"}],"html":"<p>1 עסקי חולין, משא ומתן secular occupation, trade  אבות פ״ב מ״ב: יפה תלמוד תורה עם דרך ארץ.\n2 התנהגות, נימוס good manners  סוטה מ״ד ע״א: למדה תורה דרך ארץ.\n3 זיווג, תשמיש euph. sexual connection  גיט׳ ע׳ ע״א: דרך ודרך ארץ.</p>","notation":["Marked biblical in source"]},"36560":{"h":"דַּרְכֵי שָׁלוֹם","r":"KRU05525","alt":[],"source":"krupnik","glosses":[{"text":"equity","label":""}],"html":"<p>חיי שלום equity  סנה׳ ס״ה ע״ב: מפני דרכי שלום.</p>","notation":[]},"36561":{"h":"דַּרְכָּא","r":"KRU05526","alt":[],"source":"krupnik","glosses":[{"text":"manner, way","label":""}],"html":"<p>מנהג manner, way  קיד׳ ב׳ ע״ב: דרכא דמיכלא יתירא.</p>","notation":["ז׳"]},"36562":{"h":"דָּרְכָא","r":"KRU05527","alt":[],"source":"krupnik","glosses":[{"text":"threshing","label":"1"},{"text":"threshing time","label":"2"}],"html":"<p>1 דישה threshing  תרג׳ יב״ע דבר׳ כ״ה ד׳ (שור בדישו): תורא בשעת דרכיה.\n2 דיש threshing time  שם ויקר׳ כ״ו ה׳ (והשיג לכם דיש את בציר): ויארע לכון דרכא ית קיטפא.</p>","notation":["ז׳"]},"36563":{"h":"דַּרְכּוֹן","r":"KRU05528","alt":[],"source":"krupnik","glosses":[{"text":"Daric, a persian gold coin","label":"1"}],"html":"<p>1 מין מטבע זהב Daric, a persian gold coin  שקל׳ ב׳ א׳: דרכונות.\n2 עי׳ יַרְבּוּז. ירוש׳ כלא׳ פ״א כ״ז ע״א: הרכיב תריד על גבי דרכון. </p>","notation":["ז׳"]},"36564":{"h":"דרם","r":"KRU05530","alt":[],"source":"krupnik","glosses":[{"text":"to turn southward","label":"הפ׳,"}],"html":"<p>הפ׳, הִדְרִים פנה לצד דרום to turn southward  ב״ב כ״ה ע״ב: הרוצה שיחכים ידרים ושיעשיר יצפין.</p>","notation":["Source marks no qal form"]},"36565":{"h":"דַּרְמוּסְקוּס","r":"KRU05532","alt":[],"source":"krupnik","glosses":[{"text":"Damascus","label":""}],"html":"<p>עיר דמשק Damascus  ב״ר מ״ד: הקדמני – דרמוסקוס.</p>","notation":[]},"36566":{"h":"דרמינון","r":"KRU05533","alt":[],"source":"krupnik","glosses":[{"text":"a marmalade of quinces and roses","label":""}],"html":"<p>מין מאכל מפירות שונים a marmalade of quinces and roses  ירוש׳ שביעי׳ פ״ז ל״ז ע״ב: דרמינון שרי.</p>","notation":["ז׳","Source emendation: רוֹדוֹמִילוֹן"]},"36567":{"h":"דַּרְמַסְקוֹס","r":"KRU05534","alt":[],"source":"krupnik","glosses":[{"text":"Damascus","label":""}],"html":"<p>עיר דמשק Damascus  ילק׳ בר׳ ע״ח: חקיני דרמסקוס.</p>","notation":[]},"36568":{"h":"דַּרְמַסְקִינָא","r":"KRU05535","alt":["דַּרְמַסְקָן"],"source":"krupnik","glosses":[{"text":"Damascene plum","label":""}],"html":"<p>שזיף דמשקי Damascene plum  ירוש׳ שבת פ״א ד׳ ע״א: אייתון ליה דרמסקינא; תוס׳ תר׳ ז׳ י״ג: דרמסקנין.</p>","notation":["נ׳"]},"36569":{"h":"דַּרְמֶשֶׂק","r":"KRU05536","alt":[],"source":"krupnik","glosses":[{"text":"Damascus","label":""}],"html":"<p>עיר דמשק Damascus  ירוש׳ קיד׳ פ״א ס״א ע״ד: דרמשק.</p>","notation":[]},"36570":{"h":"דַּרְנָא","r":"KRU05537","alt":[],"source":"krupnik","glosses":[{"text":"worm, moth","label":""}],"html":"<p>תולעת, עש worm, moth  שבת צ״ה ע״א: יריעה שנפל בה דרנא.</p>","notation":["ז׳"]},"36571":{"h":"דָּרַס","r":"KRU05539","alt":[],"source":"krupnik","glosses":[{"text":"to stamp","label":""},{"text":"to press (the knife)","label":""},{"text":"to throttle","label":""},{"text":"to stuff","label":""},{"text":"to be trodden down","label":""}],"html":"<p>1) דרך וצעד to stamp  ב״ק פ״ב ע״א: דרסה על הכלי. 2) דחק (את הסכין) to press (the knife)  חול׳ ל׳ ע״א: אין חוששין שמא ידרוסו זה אל זה. 3) טרף וחנק to throttle  חול׳ נ״ג ע״א: דרס שועל רחל. 4) הלעיט to stuff  שבת פ״ד מ״ג: אין אובסין את הגמל ולא דורסין. נִדְרַס נפ׳, נרמס to be trodden down  ב״מ כ״ב ע״ב: סימן העשוי לידרס לא הוי סימן. </p>","notation":["פעו״י"]},"36572":{"h":"דְּרָסָה","r":"KRU05541","alt":[],"source":"krupnik","glosses":[{"text":"pressing the knife","label":"2"}],"html":"<p>1 עי׳ דְּרִיסָה. ירוש׳ שבת פ״א ב׳ ע״ד: המעכב דרסה. \n2 דחיקת הסכין בשחיטה pressing the knife  חול׳ ט׳ ע״א: שהייה דרסה חלדה הגרמה עיקור.</p>","notation":["נ׳"]},"36573":{"h":"דְּרַע","r":"KRU05542","alt":[],"source":"krupnik","glosses":[{"text":"to sow","label":""}],"html":"<p>זרע to sow  תרג׳ קה׳ ב׳ ה׳: ודרעית תמן כל מיני עסבין.</p>","notation":["פ״י"]},"36574":{"h":"דְּרַע²","r":"KRU05543","alt":[],"source":"krupnik","glosses":[{"text":"seed","label":"1"},{"text":"offspring","label":"2"}],"html":"<p>1 זרע, מזרע seed  תרג׳ יב״ע בראש׳ ד׳ ג׳: מדרע כיתנא.\n2 צאצאים offspring  תרג׳ תהל׳ ל״ז כ״ו (וזרעו לברכה): ודרעיה לברכתא.</p>","notation":["ז׳"]},"36575":{"h":"דְּרָעָה","r":"KRU05544","alt":[],"source":"krupnik","glosses":[{"text":"arm","label":"1"},{"text":"the T’filla of the arm","label":"2"}],"html":"<p>1 זרוע arm  בר׳ ה׳ ע״ב: גלייה לדרעיה.\n2 תפלין של יד the T’filla of the arm  יומ׳ ל״ג ע״ב: עבורי דרעא אטוטפתא.</p>","notation":["ז׳"]},"36576":{"h":"דְּרַפְתְּקָא","r":"KRU05545","alt":[],"source":"krupnik","glosses":[{"text":"receptacle","label":""}],"html":"<p>בית קבול receptacle  סנה׳ צ״ט ע״א: כולהו גופי דרפתקי נינהו.</p>","notation":["ז׳"]},"36577":{"h":"דַּרְצוֹנָא","r":"KRU05546","alt":[],"source":"krupnik","glosses":[{"text":"chinese wood, cinnamon","label":""}],"html":"<p>קנמון chinese wood, cinnamon  שבת ס״ח ע״א: זנגבילא אי נמי דרצונא.</p>","notation":["ז׳"]},"36578":{"h":"דְּרַק","r":"KRU05547","alt":[],"source":"krupnik","glosses":[{"text":"to throw","label":"1"},{"text":"to sprinkle","label":"2"}],"html":"<p>1 השליך to throw  תרג׳ יב״ע שמות י״ט י״ג: גירין דאישא ידרקון ביה.\n2 הזה to sprinkle  תרג׳ דה״י ב׳ כ״ט כ״ב (ויזרקו הדם המזבחה): ודריקו אדמא למדבחא.</p>","notation":["פ״י"]},"36579":{"h":"דְּרָקוֹן","r":"KRU05548","alt":["דְּרָקוֹנָא"],"source":"krupnik","glosses":[{"text":"dragon","label":""}],"html":"<p>נחש dragon  ירוש׳ ע״ז פ״ג מ״ב ע״ד: איזהו דרקון כל שציצין יוצאין מצוארו; גיט׳ נ״ז ע״א: אתא דרקונא שמטיה לכרכשא.</p>","notation":[]},"36580":{"h":"דְּרָרָא","r":"KRU05549","alt":[],"source":"krupnik","glosses":[{"text":"object","label":""}],"html":"<p>ענין object  ב״מ ב׳ ע״ב: דררא דממונא; חגיגה כ״א ע״ב: דררא דטומאה.</p>","notation":["ז׳"]},"36581":{"h":"דְּרַרְיָא","r":"KRU05550","alt":[],"source":"krupnik","glosses":[{"text":"diarrhoea","label":""}],"html":"<p>שלשול diarrhoea  ויק״ר פי״ח: לזרא – ר׳ אביתר אומר לדרריא (לגי׳ הערוך).</p>","notation":["נ׳"]},"36582":{"h":"דָּרַשׁ","r":"KRU05551","alt":[],"source":"krupnik","glosses":[{"text":"to lecture","label":""},{"text":"to be interpreted","label":""}],"html":"<p>הורה, לימד בצבור to lecture  שמח׳ פ״ח: ישב ודרש. נִדְרַשׁ נפ׳. – נלמד ע״ד הדרוש to be interpreted  ספרא פתיחה: ל״ב מדות שהתורה נדרשת בהן. הִתְדָּרֵשׁ התפ׳, כנ״ל. ירוש׳ כת׳ פ״ג כ״ז ע״ד: תלמוד הימנה לגזירה שוה מתדרש ולו תהיה. </p>","notation":["Marked biblical in source"]},"36583":{"h":"דְּרַשׁ","r":"KRU05552","alt":[],"source":"krupnik","glosses":[{"text":"to interpret","label":""},{"text":"to lecture","label":""}],"html":"<p>1) פירש ע״ד הדרוש to interpret  סוכה נ״ב: קרא אשכחו ודרוש. 2) הורה בצבור to lecture  בר׳ כ״ח ע״א: נדרוש מר חדא שבתא ומר חדא שבתא. אִידְּרִישׁ אתפ׳ עי׳ נִדְרַשׁ. בר׳ ס״ג ע״א: האי קרא וכו׳ מידריש. </p>","notation":["פ״י"]},"36584":{"h":"דְּרָשָׁא","r":"KRU05553","alt":["דְּרָשָׁה"],"source":"krupnik","glosses":[{"text":"interpretation","label":""}],"html":"<p>פירוש ע״ד דרוש interpretation  פסח׳ פ״ב ע״ב: ת׳ גמלי דדרשה; יבמ׳ כ״ד ע״ד: כוליה קרא לדרשא אתי.</p>","notation":[]},"36585":{"h":"דַּרְשָׁן","r":"KRU05554","alt":[],"source":"krupnik","glosses":[{"text":"lecturer","label":"1"},{"text":"lawyer","label":"2"}],"html":"<p>1  lecturer  ויק״ר ל׳: פייטן ודרשן.\n2  lawyer  ב״ב קי״ט ע״ב: בנות צלפחד דרשניות.</p>","notation":[]},"36586":{"h":"דַּרְתָּא","r":"KRU05555","alt":[],"source":"krupnik","glosses":[{"text":"dwelling","label":""}],"html":"<p>דירה dwelling  יומ׳ ע״ב ע״ב: חבל על דלית ליה דרתא ותרעא לדרתיה עביד.</p>","notation":["נ׳"]},"36587":{"h":"דָּשָׁא","r":"KRU05556","alt":[],"source":"krupnik","glosses":[{"text":"door","label":""}],"html":"<p>דלת door  חול׳ כ״ב ע״ב: אתחיד דשא באפיה ומחייה לדשא.</p>","notation":["ז׳"]},"36588":{"h":"דַּשְׁדֵּשׁ","r":"KRU05557","alt":[],"source":"krupnik","glosses":[{"text":"to stamp","label":""}],"html":"<p>רמס to stamp  תרג׳ יש׳ י״ט י״ד (מובס): מדשדש.</p>","notation":["פ״י"]},"36589":{"h":"דָּשׁוֹשׁ","r":"KRU05558","alt":["דָּשׁוֹשָׁא"],"source":"krupnik","glosses":[{"text":"groats-maker","label":""}],"html":"<p>כותת גריסין groats-maker  מ״ק ב׳ ה׳: הדשושות; שם י״ג ע״ב: דשושי חילקא.</p>","notation":[]},"36590":{"h":"דִּשֵּׁן","r":"KRU05561","alt":[],"source":"krupnik","glosses":[{"text":"to become unfit","label":"נִדַּשֵּׁן נתפ׳, 1"},{"text":"to become sappy","label":"נִדַּשֵּׁן נתפ׳, 2"}],"html":"<p>נִדַּשֵּׁן נתפ׳, 1 נפסל to become unfit  מנח׳ פ״ח ע״ב: נר שכבתה נידשן השמן וכו׳.\nנִדַּשֵּׁן נתפ׳, 2 נעשה שמן ומדושן to become sappy  פדר״א ל״ב: ונדשנו עצמותיו.</p>","notation":["Marked biblical in source"]},"36591":{"h":"דָּשְׁנָא","r":"KRU05562","alt":[],"source":"krupnik","glosses":[{"text":"present","label":""}],"html":"<p>מתנה present  סנה׳ ל״ד ע״ב: האי דשנא להיא פרדשנא.</p>","notation":["ז׳"]},"36592":{"h":"דִּשְׁקְתָא","r":"KRU05563","alt":[],"source":"krupnik","glosses":[{"text":"handle","label":""}],"html":"<p>בית יד handle  ירוש׳ עיר׳ פ״ה כ״ב ע״ד: דשקתא דגזוראי.</p>","notation":["נ׳"]},"36593":{"h":"דַּשְׁרָא","r":"KRU05564","alt":[],"source":"krupnik","glosses":[{"text":"beam","label":""}],"html":"<p>קורה beam  תרג׳ אסת׳ א׳ ו׳: דשרין סגלגלין.</p>","notation":["ז׳"]},"36594":{"h":"דַּשֵּׁשׁ","r":"KRU05565","alt":[],"source":"krupnik","glosses":[{"text":"to stamp upon","label":"פַעל,"},{"text":"to pound","label":"אֲדַשׁ אפ׳"}],"html":"<p>פַעל, רמס to stamp upon  תרג׳ אסת׳ ו׳ א׳: ועזרתכא דשישו בעלי דבבנא.\nאֲדַשׁ אפ׳ דק to pound  תרג׳ ירוש׳ במדב׳ י״א ח׳ (דכו במדוכה): אדשין יתיה במזיכתא.</p>","notation":[]},"36595":{"h":"דַּשְׁתָּאָה","r":"KRU05567","alt":[],"source":"krupnik","glosses":[{"text":"thresher","label":""}],"html":"<p>מי שדש thresher  מנח׳ כ״ב ע״א: דדשו ביה דשתאי.</p>","notation":["ז׳"]},"36596":{"h":"דִּשְׁתָּנָא","r":"KRU05569","alt":[],"source":"krupnik","glosses":[{"text":"a menstruous woman","label":""}],"html":"<p>נדה a menstruous woman  ע״ז כ״ד ע״ב: כמאן קרו פרסאי לנדה דשתנא.</p>","notation":["נ׳"]},"36597":{"h":"דָּת","r":"KRU05571","alt":[],"source":"krupnik","glosses":[{"text":"religion","label":""}],"html":"<p>אמונה ותורה religion  סוכה נ״ו ע״ב: המירה דתה.</p>","notation":["Marked biblical in source"]},"36598":{"h":"דַּתְּ","r":"KRU05572","alt":[],"source":"krupnik","glosses":[{"text":"as thou","label":""}],"html":"<p>שאתה as thou  ירוש׳ סנה׳ פ״י כ״ח ע״ג: כמה דת מר אני בצדק וכו׳.</p>","notation":["Equivalent spelling: דְּאַתְּ"]},"36599":{"h":"הֵ״א","r":"KRU05576","alt":[],"source":"krupnik","glosses":[{"text":"name of the fifth letter of the Alphabet","label":""}],"html":"<p>שם האות החמישית באלף־בית name of the fifth letter of the Alphabet  ירוש׳ מע״ש פ״ה נ״ו ע״א: בין ה״א לחי״ת.</p>","notation":[]},"36600":{"h":"הָא","r":"KRU05577","alt":[],"source":"krupnik","glosses":[{"text":"this","label":"1"},{"text":"here","label":"2"},{"text":"then, of course","label":"3"},{"text":"this means to say) but..","label":"4"},{"text":"oh! (interjection)","label":"5"}],"html":"<p>1  this  כר׳ ט״ו ע״ב: הא דידיה והא דרביה.\n2 כאן here  ב״ק י״ב ע״א: הא עולא.\n3 הלא then, of course  יומא י״ג ע״א: מיתא הך הא קיימא הא.\n4 אבל (this means to say) but..  ירוש׳ סוכה פ״ה נ״ה ע״א: הא של קרבן דוחה.\n5  oh! (interjection)  נדר׳ ט״ו ע״ב: הא קרבן שאוכל לך.</p>","notation":[]},"36601":{"h":"הָא וְהָא","r":"KRU05578","alt":[],"source":"krupnik","glosses":[{"text":"both","label":""}],"html":"<p>גם זה וגם זה both  תענ׳ כ״ה ע״א: הא והא גרמא ליה.</p>","notation":[]},"36602":{"h":"הַאֲזָנָה","r":"KRU05579","alt":[],"source":"krupnik","glosses":[{"text":"close attention","label":""}],"html":"<p>הקשבה close attention  ספרי דב׳ ש״ו: האזנה ושמיעה לשמים.</p>","notation":["נ׳"]},"36603":{"h":"הַאי","r":"KRU05580","alt":[],"source":"krupnik","glosses":[{"text":"this, that","label":""}],"html":"<p>זה, זאת this, that  בר׳ ו׳ ע״א: האי מאן דבעי.</p>","notation":["מה״ג"]},"36604":{"h":"הַאי מַאי","r":"KRU05581","alt":[],"source":"krupnik","glosses":[{"text":"what is that? (i.e. this is no argument)","label":""}],"html":"<p>מה זאת? מה ענין זה לכאן? what is that? (i.e. this is no argument)  עיר׳ י׳ ע״א: האי מאי אי אמרת בשלמא וכו׳.</p>","notation":[]},"36605":{"h":"הָאִידְנָא","r":"KRU05582","alt":[],"source":"krupnik","glosses":[{"text":"now, to-day","label":""}],"html":"<p>כעת, עכשיו now, to-day  קיד׳ ע״א ע״ב: והאידנא דאיכא רמאי.</p>","notation":["תה״פ"]},"36606":{"h":"הָאֵיךְ","r":"KRU05583","alt":[],"source":"krupnik","glosses":[{"text":"how?","label":""}],"html":"<p>כיצד how?  ירוש׳ ע״ז פ״ב מ״ה: האיך אתה קורא.</p>","notation":["מה״ש"]},"36607":{"h":"הַאִיךְ","r":"KRU05584","alt":[],"source":"krupnik","glosses":[{"text":"the former","label":""}],"html":"<p>הלא, ההוא the former  ר״ה ב׳ ע״ב: בשלמא האיך וכו׳ אלא האי.</p>","notation":["מה״ג"]},"36608":{"h":"הָאל","r":"KRU05585","alt":[],"source":"krupnik","glosses":[{"text":"farther off (of space)","label":""}],"html":"<p>הלאה farther off (of space)  תרג׳ יב״ע בר׳ ל״ב כ״ה: מן האל לנחלא.</p>","notation":["תה״פ"]},"36609":{"h":"הַאֲמָנָה","r":"KRU05586","alt":[],"source":"krupnik","glosses":[{"text":"confirmation","label":"1"},{"text":"faith","label":"2"}],"html":"<p>1 קיום ואישור confirmation  שבוע׳ ל״ו ע״א: האמנת דברים.\n2 אמונה faith  שמו״ר כ״ב: ובזכות האמונה שהאמינו.</p>","notation":["נ׳"]},"36610":{"h":"הָאנָא","r":"KRU05587","alt":[],"source":"krupnik","glosses":[{"text":"behold I …","label":""}],"html":"<p>הנני behold I …  תרג׳ יר׳ כ״ג ל״ב (הנני): האנא.</p>","notation":["מה״ג"]},"36611":{"h":"הָאַסְטוּ","r":"KRU05588","alt":[],"source":"krupnik","glosses":[{"text":"oh!","label":""}],"html":"<p>אהה oh!  ירוש׳ שבי׳ פ״ד ל״ה ע״א: האסטו שרי לכון מירדי! ?</p>","notation":["מה״ק"]},"36612":{"h":"הֲאָרָה","r":"KRU05589","alt":[],"source":"krupnik","glosses":[{"text":"kindling","label":""}],"html":"<p>הדלקה kindling  ספרא צו פרשה י״א פרק ט״ז: הארת הנרות.</p>","notation":["נ׳"]},"36613":{"h":"הֲאָרַת פָּנִים","r":"KRU05590","alt":[],"source":"krupnik","glosses":[{"text":"benevolence","label":""}],"html":"<p>סבר פנים יפות benevolence  מדרש תהל׳ סוף ה׳: אין לנו אלא הארת פניך הושיענו ונושע.</p>","notation":[]},"36614":{"h":"הֲבָאָה","r":"KRU05591","alt":[],"source":"krupnik","glosses":[{"text":"offering","label":"1"},{"text":"bringing about","label":"2"}],"html":"<p>1 הקרבה offering  ספרי נשא ל״ה: עד הבאת קרבן.\n2 גרם וסיבוב bringing about  פאה כ״א מ״א: הבאת שלום.</p>","notation":["נ׳"]},"36615":{"h":"הֲבַאי","r":"KRU05592","alt":[],"source":"krupnik","glosses":[{"text":"exaggeration","label":""}],"html":"<p>גוזמא והפלגה exaggeration  נדר׳ פ״ג מ״א: נדרי הבאי.</p>","notation":["ז׳"]},"36616":{"h":"הַבְאָשָׁה","r":"KRU05593","alt":[],"source":"krupnik","glosses":[{"text":"disfigurement through disease","label":""}],"html":"<p>כיעור מחמת מחלה disfigurement through disease  ילק׳ דב׳ תתקמ״ב: ואין בני אדם באין לידי הבאשה אלא וכו׳.</p>","notation":["נ׳"]},"36617":{"h":"הַבְדָּלָה","r":"KRU05594","alt":[],"source":"krupnik","glosses":[{"text":"cutting apart","label":"1"},{"text":"separation","label":"2"},{"text":"a formula of prayer for the exit of the Sabbath or festivals","label":"3"}],"html":"<p>1 הסרה והפרזה cutting apart  חול׳ כ״א ע״א: הבדלת עולת העוף.\n2 הפרשה separation  ב״ר פ״ג: ויבדל הבדלה ממש.\n3 ברכת הבדלה במוצאי שבת ויום טוב a formula of prayer for the exit of the Sabbath or festivals  תוס׳ בר׳ ו׳ ו׳: ואומר הבדלה במוצאי שבת ויום טוב.</p>","notation":["נ׳"]},"36618":{"h":"הִבְהֵב","r":"KRU05596","alt":[],"source":"krupnik","glosses":[{"text":"to singe, to parch","label":""},{"text":"to nod consent","label":""},{"text":"to be affected by flames","label":""}],"html":"<p>1) פ״י חרך, קלה to singe, to parch  ירוש׳ מעש׳ פ״ד נ״א ע״א: המהבהב שיבולין באור. 2) פ״ע הסכים למחצה to nod consent  בר׳ ל״ד ע״א: פעם ראשונה יסרב ב׳ מהבהב וכו׳. נִתְהַבְהֵב נתפ׳, נחרך to be affected by flames  יומא מ״א ע״ב: נתהבהב הלשון. </p>","notation":[]},"36619":{"h":"הַבָּטָה","r":"KRU05597","alt":[],"source":"krupnik","glosses":[{"text":"looking at","label":"1"},{"text":"watching ownerless objects","label":"2"}],"html":"<p>1 ראייה מקרוב, הצצה looking at  איכ״ר א׳ א׳: הבטה מקרוב ראייה מרחוק\n2 שימת־לב ונתינת־דעת watching ownerless objects  ב״מ קי״ח ע״א: הבטה בהפקר קני.</p>","notation":["נ׳"]},"36620":{"h":"הַבְטָחָה","r":"KRU05598","alt":[],"source":"krupnik","glosses":[{"text":"assurance, confidence","label":"1"},{"text":"promise","label":"2"},{"text":"faith","label":"3"}],"html":"<p>1 בטחון, ודאות assurance, confidence  ברכו׳ פ״ה מ״ד: ואם הבטחתו שהוא נושא את כפיו וכו׳.\n2 יעוד promise  שמו״ר ל״ח: ואחר רד״ו שנים באתה ההבטחה שהבטיח הקב״ה את הצדיק.\n3 אמון faith  מכי׳ יתרו ב׳: אנשי אמת אלו בעלי הבטחה.</p>","notation":["נ׳"]},"36621":{"h":"הבל","r":"KRU05599","alt":[],"source":"krupnik","glosses":[{"text":"to begin to steam","label":"הֶהֱבִיל הפ׳"}],"html":"<p>הֶהֱבִיל הפ׳ הוציא הבל ואד to begin to steam  שבת פ״א מ״ו: אין נותנין אונין של פשתן לתוך התנור אלא כדי שיהבילו מבעוד יום.</p>","notation":["Source marks no qal form"]},"36622":{"h":"הֶבֶל","r":"KRU05600","alt":[],"source":"krupnik","glosses":[{"text":"vapor","label":""}],"html":"<p>·– אד vapor  ירוש׳ ע״ז פ״ג מ״ב ע״ד: שהבל המרחץ רע לשנים.</p>","notation":[]},"36623":{"h":"הֶבְלָא","r":"KRU05602","alt":["הֲבָלוּ","הֲבָלוּתָא"],"source":"krupnik","glosses":[{"text":"vanity","label":""}],"html":"<p>הבל, דבר שאין בו ממש vanity  תרג׳ איוב כ״ז י״ב (הבל): הבלא; קה׳ א׳ ב׳ (הבל): הבלו; שם י״א ח׳ (הבל): הבלותא.</p>","notation":["ז׳"]},"36624":{"h":"הַבְלָעָה","r":"KRU05603","alt":[],"source":"krupnik","glosses":[{"text":"payment for a thing included in the bargain (and not mentioned)","label":""}],"html":"<p>הוספת דבר קטן על דבר גדול, ביחוד מחיר דבר קטן הנכלל במחיר דבר גדול payment for a thing included in the bargain (and not mentioned)  עיר׳ מ״ד ע״ב: מר סבר הבלעת תחומין מילתא היא; שם כ״ז ע״ב: שנתן דמי מים ומלח בהבלעה.</p>","notation":["נ׳"]},"36625":{"h":"הֶבְעֵר","r":"KRU05606","alt":[],"source":"krupnik","glosses":[{"text":"damage through carelessness in handling fire","label":""}],"html":"<p>גרם שריפה damage through carelessness in handling fire  ב״ק פ״א מ״א: ארבעה אבות נזיקין השור והבור והמבעה וההבער.</p>","notation":["ז׳"]},"36626":{"h":"הַבְעָרָה","r":"KRU05607","alt":[],"source":"krupnik","glosses":[{"text":"the kindling of fire","label":"1"},{"text":"destruction","label":"2"}],"html":"<p>1 הדלקה the kindling of fire  שבת ע׳ ע״א: הבערה שהיא אב מלאכה וכו׳.\n2 ביעור והשמדה destruction  ירוש׳ סנה׳ פ״ז כ״ד ע״ב: נאמר כאן ובערת הרע מקרבך ונאמר להלן ואתה תבער וכו׳ הבערה הבערה וכו׳.</p>","notation":["נ׳"]},"36627":{"h":"הַבְרָא","r":"KRU05609","alt":[],"source":"krupnik","glosses":[{"text":"darkness","label":""}],"html":"<p>חושך darkness  תמיד ל״ב ע״א: דפרשי בהברא.</p>","notation":["ז׳"]},"36628":{"h":"הַבְרָאָה","r":"KRU05610","alt":[],"source":"krupnik","glosses":[{"text":"recovery to health","label":"1"}],"html":"<p>1 שיבה לבריאות recovery to health  שבת קל״ז ע״א: יום הבראתו כיום הולדו.\n2 עי׳ סְעוּדַת הַבְרָאָה. </p>","notation":["נ׳"]},"36629":{"h":"הֲבָרָה","r":"KRU05611","alt":[],"source":"krupnik","glosses":[{"text":"noise","label":"1"},{"text":"rumour","label":"2"}],"html":"<p>1 שאון noise  ר״ה פ״ג מ״ז: אם קול שופר שמע יצא ואם קול הברה שמע לא יצא.\n2 שמועה rumour  ירוש׳ דמאי פ״א כ״ב ע״א: נפלה הברה בעיר באת בתו של אותו איש.</p>","notation":["נ׳"]},"36630":{"h":"הַגְבָּהָה","r":"KRU05613","alt":[],"source":"krupnik","glosses":[{"text":"lifting, taking up","label":"1"},{"text":"elevation","label":"2"}],"html":"<p>1 הרמה מן הקרקע lifting, taking up  קיד׳ פ״א מ״ד: בהמה גסה נקנית במסירה ודקה בהגבהה.\n2 התרוממות elevation  שמו״ר פמ״ה: השפלתי זו הגבהתי.</p>","notation":["נ׳"]},"36631":{"h":"הַגְבָּלָה","r":"KRU05614","alt":[],"source":"krupnik","glosses":[{"text":"setting bounds","label":""}],"html":"<p>קביעת גבול setting bounds  שבת פ״ז ע״א: מצות הגבלה.</p>","notation":["נ׳"]},"36632":{"h":"הַגָּדָה","r":"KRU05615","alt":[],"source":"krupnik","glosses":[{"text":"telling, evidence","label":"1"},{"text":"Haggadah, the home service on Passover nights","label":"3"}],"html":"<p>1 אמירה והרצאה telling, evidence  סנה׳ ל׳ ע״ב: מקשינן הגדה לראייה.\n2 עי׳ אַגָּדָה. חגי׳ י״ד ע״א: מה לך אצל הגדה כלך לך אצל נגעים ואהלות. \n3 סדר הגדה של פסח Haggadah, the home service on Passover nights  פסח׳ קט״ז ע״ב: סומא פטור מלומר הגדה.</p>","notation":["נ׳"]},"36633":{"h":"הֶגְדֵּר","r":"KRU05616","alt":[],"source":"krupnik","glosses":[{"text":"i>Ersatzwort (Beiname) für","label":""}],"html":"<p>כינויים להקדש a word made up as substitute for הקדש | &lt;i&gt;Ersatzwort (Beiname) für הקדש ירוש׳ נדר׳ פ״א ל״ו ע״ג: הגדר הגזר וכו׳.</p>","notation":["ז׳"]},"36634":{"h":"הָגָה","r":"KRU05617","alt":[],"source":"krupnik","glosses":[{"text":"to spell, to pronounce","label":""},{"text":"to be spelled","label":""}],"html":"<p>ביטא to spell, to pronounce  סנה׳ פ״י מי״א: ההוגה את השם באותיותיו. נֶהֱגֶה נפ׳, נתבטא to be spelled  שבת פי״ב מ״ד: שתי אותיות וכו׳ נהגין זה עם זה. </p>","notation":["Marked biblical in source"]},"36635":{"h":"הָגוּן","r":"KRU05618","alt":[],"source":"krupnik","glosses":[{"text":"worthy","label":""}],"html":"<p>ראוי וחשוב worthy  ספרא אמור קל״ז: מלך רשע אתה ואין אתה הגון שיעשה נס על ידך.</p>","notation":["ת׳"]},"36636":{"h":"הֲגָיָיה","r":"KRU05619","alt":[],"source":"krupnik","glosses":[{"text":"study","label":""}],"html":"<p>עיון ולמוד study  ירוש׳ בר׳ פ״א ג׳ ע״ג: שתהא הגיית יום ולילה שוין.</p>","notation":["נ׳"]},"36637":{"h":"הֶגְמוֹן","r":"KRU05621","alt":["הֶגְמוֹנָא"],"source":"krupnik","glosses":[{"text":"general","label":""}],"html":"<p>שר וגדול general  שמו״ר ל״א: הגמונים ודוכוסים; ע״ז י״א ע״א: דוכסא להגמונא.</p>","notation":[]},"36638":{"h":"הֶגְמוֹנְיָא","r":"KRU05622","alt":["הֶגְמוֹנְיָה"],"source":"krupnik","glosses":[{"text":"district","label":""}],"html":"<p>גליל district  גיט׳ פ״א מ״א; מהגמוניא להגמוניא; שם ד׳ ע״ב: שתי הגמוניות.</p>","notation":[]},"36639":{"h":"הָגַן","r":"KRU05623","alt":[],"source":"krupnik","glosses":[{"text":"to suit","label":""}],"html":"<p>היה מתאים וראוי to suit  ב״ק פ׳ ע״א: עד שימצא את ההוגנת לו.</p>","notation":["פ״ע"]},"36640":{"h":"הֶהֱגִין","r":"KRU05624","alt":[],"source":"krupnik","glosses":[{"text":"to be of the same weight","label":""}],"html":"<p>הפ׳, התאים במשקל to be of the same weight  ירוש׳ כתו׳ פ״א כ״ה ע״ב: סלעים סביריניות (צ״ל טביריניות) מהגינות.</p>","notation":[]},"36641":{"h":"הַגָּעָה","r":"KRU05625","alt":[],"source":"krupnik","glosses":[{"text":"contact","label":""}],"html":"<p>נגיעה contact  מכי׳ בוא פסחא י״א: והגעתם אל המשקוף על כל הגעה טבילה.</p>","notation":["נ׳"]},"36642":{"h":"הַגְעָלָה","r":"KRU05626","alt":[],"source":"krupnik","glosses":[{"text":"the cleaning of impure vessels by means of boiling water","label":""}],"html":"<p>צחצוח כלים ברותחין the cleaning of impure vessels by means of boiling water  ע״ז ע״ו ע״א: מריקה ושטיפה בצונן הגעלה בחמין.</p>","notation":["נ׳"]},"36643":{"h":"הֲגָפָה","r":"KRU05627","alt":[],"source":"krupnik","glosses":[{"text":"locking, shutting up","label":""}],"html":"<p>סגירה ונעילה locking, shutting up  ערכ׳ י״א ע״ב: לסייע בהגפת דלתות.</p>","notation":["נ׳"]},"36644":{"h":"הַגְרָה","r":"KRU05628","alt":[],"source":"krupnik","glosses":[{"text":"name of an Arabian district","label":""}],"html":"<p>שם ארץ בערָב name of an Arabian district  במ״ר פי״ג: גלות הגרה.</p>","notation":[]},"36645":{"h":"הַגְרוֹנְיָא","r":"KRU05630","alt":[],"source":"krupnik","glosses":[{"text":"name of a Babylonian town","label":""}],"html":"<p>שם עיר בבבל name of a Babylonian town  שבת י״א ע״א: סבי דהגרוניא.</p>","notation":[]},"36646":{"h":"הַגְרָלָה","r":"KRU05631","alt":[],"source":"krupnik","glosses":[{"text":"casting lots","label":""}],"html":"<p>הטלת גורל casting lots  יומא מ׳ ע״א: מת אחד מהן מביא חבירו שלא בהגרלה.</p>","notation":["נ׳"]},"36647":{"h":"הֶגְרֵם","r":"KRU05632","alt":[],"source":"krupnik","glosses":[{"text":"i>Ersatzname (Beiname) für","label":""}],"html":"<p>כנוי להקדש a word formed as a substitute of הקדש | &lt;i&gt;Ersatzname (Beiname) für הקדש. ירוש׳ נדר׳ פ״א ל״ו ע״ג: הגדר הגזר הגרם.</p>","notation":["ז׳"]},"36648":{"h":"הַגְרָמָה","r":"KRU05633","alt":[],"source":"krupnik","glosses":[{"text":"cutting the animal’s throat in a slanting direction (letting the knife slide beyond the space ritually designated for cutting)","label":""}],"html":"<p>שימוט הסכין ונטיתה ממקום השחיטה בגרון בעל-החי cutting the animal’s throat in a slanting direction (letting the knife slide beyond the space ritually designated for cutting)  חול׳ ט׳ ע״א: ואלו הן הלכות שחיטה שהיה דרסה חלדה הגרמה ועיקור.</p>","notation":["נ׳"]},"36649":{"h":"הַגָּשָׁה","r":"KRU05634","alt":[],"source":"krupnik","glosses":[{"text":"drawing near","label":"1"},{"text":"bringing near, offering","label":"2"}],"html":"<p>1 קריבה drawing near  ב״ר פמ״ט: הגשה למלחמה וכו׳ לפיוס וכו׳ לתפלה.\n2 הבאה, הקרבה bringing near, offering  מנח׳ פ״ה מ״ה: וכל שאין בהן קמיצה אין בהן הגשה.</p>","notation":["נ׳"]},"36650":{"h":"הָדָא","r":"KRU05637","alt":[],"source":"krupnik","glosses":[{"text":"this","label":""}],"html":"<p>זה, זאת this  ב״ר פ״ב: הדא הוא דכתיב.</p>","notation":["מה״ג"]},"36651":{"h":"הֲדָדֵי","r":"KRU05638","alt":[],"source":"krupnik","glosses":[{"text":"each other, mutually","label":""}],"html":"<p>זה את זה each other, mutually  גיט׳ ס״ח ע״א: כבשינהו אהדדי; שם ס״ט ע״א: בהדי הדדי.</p>","notation":["תה״פ"]},"36652":{"h":"הֲדוֹסְטָא","r":"KRU05640","alt":[],"source":"krupnik","glosses":[{"text":"half-shoe","label":""}],"html":"<p>מין נעל half-shoe  ירוש׳ שבת פ״ו ח׳ ע״א: סנדל מסומר וכו׳ הדוסטא.</p>","notation":["ז׳"]},"36653":{"h":"הָדוּף","r":"KRU05641","alt":[],"source":"krupnik","glosses":[{"text":"hurried","label":""}],"html":"<p>חטוף hurried  ירוש׳ בכורים פ״ב פ״ד ע״א: מיתה הדופה.</p>","notation":["ת׳"]},"36654":{"h":"הֲדוֹרָה","r":"KRU05642","alt":[],"source":"krupnik","glosses":[{"text":"return","label":""}],"html":"<p>חזרה return  ירוש׳ הור׳ פ״ג מ״ח ע״א: בהדורת רבותינו.</p>","notation":["נ׳"]},"36655":{"h":"הֲדוּרֵי","r":"KRU05643","alt":[],"source":"krupnik","glosses":[{"text":"steep hill","label":""}],"html":"<p>מקום תלול steep hill  ב״ב י״ב ע״א: דזרע בהדורי.</p>","notation":["ז״ר"]},"36656":{"h":"הֲדָחָה","r":"KRU05644","alt":[],"source":"krupnik","glosses":[{"text":"rinsing","label":""}],"html":"<p>צחצוח ע״י מים rinsing  בר׳ נ״א ע״א: הדחה מבפנים ושטיפה מבחוץ.</p>","notation":["נ׳"]},"36657":{"h":"הַדָּחָה","r":"KRU05645","alt":[],"source":"krupnik","glosses":[{"text":"enticement","label":""}],"html":"<p>פיתוי והסתה enticement  ספרי ראה פ״ו: מה הדחה האמורה להלן בסקילה וכו׳.</p>","notation":["נ׳"]},"36658":{"h":"הֶדְיָא","r":"KRU05646","alt":[],"source":"krupnik","glosses":[{"text":"explicitly","label":""},{"text":"openly","label":""},{"text":"directly","label":""}],"html":"<p>1) בפירוש explicitly  שבת קל״ג ע״ב: בהדיא כתיב ביה. 2) בפומבי openly  סנה׳ ל״ט ע״א: לשקולי בהדיא. לְהֶדְיָא ישר directly  בכורות מ״ד ע״ב: האי איתתא לא תקום להדיא באנפי ינוקא. </p>","notation":["תה״פ","Used in: בְּהֶדְיָא"]},"36659":{"h":"הֶדְיוֹט","r":"KRU05647","alt":[],"source":"krupnik","glosses":[{"text":"common, popular, private","label":"1"},{"text":"untrained man, commoner, ignorant","label":"2"}],"html":"<p>1  common, popular, private  יבמ׳ נ״ט ע״א: כהן הדיוט; ב״ר צ״ו: משל הדיוט; רות רבה א׳ י״ט: פרה הדיוטית.\n2  untrained man, commoner, ignorant  מו״ק ח׳ ע״ב: הדיוט וכו׳ אומן; מגי׳ י״ב ע״ב: הדיוט קופץ בראש.</p>","notation":[]},"36660":{"h":"הַדְיוֹךְ","r":"KRU05648","alt":[],"source":"krupnik","glosses":[{"text":"racing","label":""}],"html":"<p>מרוץ racing  ב״ר פ״י: הרבה להן בדיצה הרבה להן בהדיוכין.</p>","notation":["ז׳"]},"36661":{"h":"הַדְיֵיב","r":"KRU05649","alt":["הדיית","הדיף"],"source":"krupnik","glosses":[{"text":"Adiabena, a district of Assyria","label":""}],"html":"<p>מדינה מצפון לאשור Adiabena, a district of Assyria  קיד׳ ע״ב ע״א: תבור זו חדייב (ירוש׳ מגי׳ פ״א ע״ב ע״ד: הדיית); ב״ר פל״ז: ריפת הדיף.</p>","notation":[]},"36662":{"h":"הָדֵךְ","r":"KRU05650","alt":[],"source":"krupnik","glosses":[{"text":"this","label":""}],"html":"<p>זה this  ב״ר פ״ה: להדך ימא.</p>","notation":["מה״ג"]},"36663":{"h":"הַדְלָקָה","r":"KRU05651","alt":[],"source":"krupnik","glosses":[{"text":"kindling","label":""}],"html":"<p>הבערה, הצתה kindling  שבת פ״ב מ״ו: והדלקת הנר.</p>","notation":["נ׳"]},"36664":{"h":"הֲדַם","r":"KRU05652","alt":[],"source":"krupnik","glosses":[{"text":"to dissect","label":""}],"html":"<p>גזר לגזרים to dissect  גיט׳ ס״ז ע״ב: אהדמו לי הדמו דחיותא.</p>","notation":["פ״י"]},"36665":{"h":"הִדֵּס","r":"KRU05653","alt":[],"source":"krupnik","glosses":[{"text":"to scratch, to leave marks of the feet (esp. of chickens)","label":""}],"html":"<p>ניקר וחטט בעפר to scratch, to leave marks of the feet (esp. of chickens)  ירוש׳ ב״ק פ״ב ע״ד: תרנגולין וכו׳ הידסו עפר על גבי עיסה.</p>","notation":["פ״י"]},"36666":{"h":"הֲדַס","r":"KRU05654","alt":[],"source":"krupnik","glosses":[{"text":"the town Edessa","label":""}],"html":"<p>העיר אדסה שבארם נהרים the town Edessa  תרג׳ יב״ע בר׳ י׳ י׳ (ארך): הדס.</p>","notation":[]},"36667":{"h":"הִדֵּק","r":"KRU05655","alt":[],"source":"krupnik","glosses":[{"text":"to fasten, to squeeze","label":""}],"html":"<p>חיזק ואדק to fasten, to squeeze  מגי׳ ל״ב ע״א: הגולל ספר תורה וכו׳ וכשהוא מהדקו וכו׳; שבת קמ״א ע״א: לא ליהדוק וכו׳.</p>","notation":["פ״י"]},"36668":{"h":"הִדֵּר","r":"KRU05656","alt":[],"source":"krupnik","glosses":[{"text":"to adorn","label":"1"},{"text":"to be zealous (in religious observance)","label":"2"}],"html":"<p>1 קישט וכיבד to adorn  ויק״ר פ״ל: שהדרו הקב״ה בשיבה טובה.\n2 הקפיד ודקדק to be zealous (in religious observance)  שבת פ״א ע״ב: מצות חנוכה נר איש וביתו והמהדרין נר לכל אחד ואחד והמהדרין מן המהדרין וכו׳.</p>","notation":["פ״י"]},"36669":{"h":"הֲדַר","r":"KRU05657","alt":[],"source":"krupnik","glosses":[{"text":"to return","label":"1"},{"text":"to change his opinion","label":"2"}],"html":"<p>1 חזר to return  ב״מ י״ד ע״א: עלי דידי הדר.\n2 שב מדעתו to change his opinion  ב״ב פ״ד ע״א: לא מצית הדרת בך.</p>","notation":["פ״י"]},"36670":{"h":"הַדַּר","r":"KRU05658","alt":[],"source":"krupnik","glosses":[{"text":"to go around searching","label":"פַעל,"},{"text":"to restore","label":"אַהֲדַר אפ׳ 1"},{"text":"to repeat","label":"אַהֲדַר אפ׳ 2"},{"text":"to reply","label":"אַהֲדַר אפ׳ 3"},{"text":"to go around","label":"אַהֲדַר אפ׳ 4"}],"html":"<p>פַעל, חזר אחרי־, בקש to go around searching  חול׳ ע״ו ע״ב: הדורי אפירכי למה לך.\nאַהֲדַר אפ׳ 1 החזיר to restore  ב״מ כ״ו ע״א: אי דעתייהו לאהדורה אהדורי ניהלי.\nאַהֲדַר אפ׳ 2 שנה to repeat  מו״ק כ״ח ע״א: אהדרי לתלמודאי.\nאַהֲדַר אפ׳ 3 השיב to reply  חול׳ ל״ד ע״א: מאי אהדרי וכו׳.\nאַהֲדַר אפ׳ 4 סבב to go around  שבת קנ״א ע״ב: אהדורי אפיתחא.</p>","notation":[]},"36671":{"h":"הַדְרָא","r":"KRU05659","alt":[],"source":"krupnik","glosses":[{"text":"bowels","label":""}],"html":"<p>קרביים bowels  חול׳ מ״ח ע״ב: הדרא דכנתא.</p>","notation":["ז׳"]},"36672":{"h":"הדראה","r":"KRU05660","alt":[],"source":"krupnik","glosses":[{"text":"flour of the second course","label":""}],"html":"<p>קמח שאינו מנופה כל צרכו flour of the second course  פסח׳ ל״ז ע״א: יוצאין בפת נקייה ובהדראה (ובערוך: ובהרדאה).</p>","notation":["ת׳","Source emendation: הָרְדָּאָה"]},"36673":{"h":"הִדְרַאוְלִיס","r":"KRU05661","alt":[],"source":"krupnik","glosses":[{"text":"water-organ","label":""}],"html":"<p>עוגב של מים water-organ  תוס׳ ערכ׳ א׳ י״ג: הדראוליס לא היה במקדש וכו׳.</p>","notation":["ז׳"]},"36674":{"h":"הִדְרוֹקָן","r":"KRU05663","alt":[],"source":"krupnik","glosses":[{"text":"one afflicted with dropsy","label":"1"},{"text":"dropsy","label":"2"}],"html":"<p>1 חולה במחלת המים one afflicted with dropsy  עיר׳ מ״א ע״ב: שלשה מתין כשהן מספרין חולי מעיין וחיה והדרוקן.\n2 מחלת המים dropsy  בר׳ כ״ה ע״א: עמוד החוזר מביא את האדם לידי הדרוקן.</p>","notation":["ז׳"]},"36675":{"h":"הַדְרְיָינָא","r":"KRU05664","alt":[],"source":"krupnik","glosses":[{"text":"Hadrianic","label":""}],"html":"<p>של הדריינוס קיסר רומי Hadrianic  ע״ז נ״ב ע״ב: דינרא הדריינא.</p>","notation":["ת׳"]},"36676":{"h":"הַדְרָנָא","r":"KRU05666","alt":[],"source":"krupnik","glosses":[{"text":"inconstant, shuffling","label":""}],"html":"<p>שדרכו לחזור בו מדבריו inconstant, shuffling  כת׳ צ״ז ע״א: דלא ליקרו לה הדרניתא.</p>","notation":["ת׳"]},"36677":{"h":"הֲדַרְנִיאֵל","r":"KRU05667","alt":[],"source":"krupnik","glosses":[{"text":"name of an angel","label":""}],"html":"<p>שם מלאך name of an angel  פסיק״ר כ׳: הדרניאל המלאך.</p>","notation":[]},"36678":{"h":"הֵה","r":"KRU05668","alt":[],"source":"krupnik","glosses":[{"text":"maggot","label":""}],"html":"<p>מין תולעת maggot  שבת צ׳ ע״א: הה דרימוני.</p>","notation":["ז׳"]},"36679":{"h":"הַהֵין","r":"KRU05670","alt":["הָהָן"],"source":"krupnik","glosses":[{"text":"this","label":""}],"html":"<p>זה this  ירוש׳ גיט׳ פ״ט נ׳ ע״ב: כל ההין פירקא; סנה׳ פ״ז כ״ה ע״ד: ההן תרומה וההן מעשר.</p>","notation":[]},"36680":{"h":"הוּא","r":"KRU05672","alt":[],"source":"krupnik","glosses":[{"text":"supposed","label":""}],"html":"<p>·– בתנאי supposed  ב״ב כ״ט ע״א: ג׳ שנים שאמרו הוא שאכלן רצופות.</p>","notation":[]},"36681":{"h":"הֲוָא","r":"KRU05673","alt":[],"source":"krupnik","glosses":[{"text":"to be","label":""}],"html":"<p>היה to be  ברכות ג׳ ע״ב: ג׳ משמרות הוי.</p>","notation":["פ״ע"]},"36682":{"h":"הַוֵּי","r":"KRU05674","alt":[],"source":"krupnik","glosses":[{"text":"to oppose, to argue","label":""}],"html":"<p>שאל, הקשה to oppose, to argue  כת׳ ע״ב ע״ב: הוי בה ר׳ פפא.</p>","notation":["פַעיל"]},"36683":{"h":"הוֹאִיל","r":"KRU05676","alt":[],"source":"krupnik","glosses":[{"text":"because, since","label":""}],"html":"<p>מכיון because, since  כתוב׳ פי״ג מ״ד: הואיל והודה במקצת הטענה ישבע.</p>","notation":["מה״ח"]},"36684":{"h":"הוֹבַאי","r":"KRU05677","alt":[],"source":"krupnik","glosses":[{"text":"a species of thorn","label":""}],"html":"<p>מין שיח של קוצים a species of thorn  תרג׳ איוב ל׳ ד׳ (מלוח): הובאי.</p>","notation":["ז׳"]},"36685":{"h":"הוֹבָדָא","r":"KRU05678","alt":[],"source":"krupnik","glosses":[{"text":"destruction","label":""}],"html":"<p>איבוד destruction  תרג׳ אס׳ ט׳ ה׳ (אבדן): הובדא.</p>","notation":["ז׳"]},"36686":{"h":"הוֹבְלִילָא","r":"KRU05679","alt":[],"source":"krupnik","glosses":[{"text":"stomach","label":""}],"html":"<p>קיבה, אצטומכא stomach  שבת ל״ו ע״ב: הובלילא בי כסי.</p>","notation":["ז׳"]},"36687":{"h":"הוֹגֵין","r":"KRU05681","alt":[],"source":"krupnik","glosses":[{"text":"anchor","label":""}],"html":"<p>עוגן anchor  ירוש׳ פי״ז ט״ז ע״א: אף ההוגין.</p>","notation":["ז׳"]},"36688":{"h":"הוֹגֶן","r":"KRU05682","alt":[],"source":"krupnik","glosses":[{"text":"appropriately, reasonably","label":""}],"html":"<p>כראוי appropriately, reasonably  ב״ר פצ״ג: כהוגן וכשורה עשה.</p>","notation":["תה״פ","Used in: כְּהוֹגֶן"]},"36689":{"h":"הוֹגֶן²","r":"KRU05683","alt":[],"source":"krupnik","glosses":[{"text":"rim","label":""}],"html":"<p>אוגן, שפה לכלי rim  כלים פכ״ה מ״ו: בני כלים והוגניהם וכו׳.</p>","notation":["ז׳"]},"36690":{"h":"הוֹגֵן","r":"KRU05684","alt":[],"source":"krupnik","glosses":[{"text":"anchor","label":""}],"html":"<p>עוגן anchor  ספרי דב׳ שמ״ו: וקשרם בהוגנים.</p>","notation":["ז׳"]},"36691":{"h":"הוֹגָן","r":"KRU05685","alt":["הוֹגָנָא"],"source":"krupnik","glosses":[{"text":"camel","label":""}],"html":"<p>מין גמל camel  ירוש׳ ביצה פ״ג ס״ג ע״א: הוגן אחד גדול; ב״ר פס״ה: מרכיבין אותו על שני הוגנין.</p>","notation":[]},"36692":{"h":"הוּגְנִיסִיס","r":"KRU05686","alt":[],"source":"krupnik","glosses":[{"text":"noble descent","label":""}],"html":"<p>יחוס אבות noble descent  ב״ר פ״ק: הודעתי הוגניסיס שלי.</p>","notation":["נ׳"]},"36693":{"h":"הוֹדָאָה","r":"KRU05687","alt":["הוֹדָיָה","הוֹדָיָיה"],"source":"krupnik","glosses":[{"text":"admission","label":"1"},{"text":"thanksgiving","label":"2"}],"html":"<p>1 התוודות, הסכמה לטענת הצד השני admission  ב״מ ג׳ ע״ב: הודאת בעל דין כמאה עדים דמי; סוטה פ״ט מ״י: הודיית המעשר.\n2 תודה thanksgiving  בר׳ פ״ט מ״א: נותן הודאה על שעבר וצועק על העתיד; ירוש׳ שם פ״א ג׳ ע״ד: הודיה ושבח.\n3 הראשונה בג׳ ברכות האחרונות שבשמונה עשרה the first of the last three sections of שמונה עשרה | die erste unter den drei letzten Benediktionen in der שמונה עשרה בר׳ פ״ה מ״ב: בחונן הדעת וכו׳ בהודאה.</p>","notation":[]},"36694":{"h":"הוּדְרָא","r":"KRU05689","alt":[],"source":"krupnik","glosses":[{"text":"beam","label":""}],"html":"<p>קורה beam  ב״ב ג׳ ע״ב: שרגי ליבני והדדי הודרי וכו׳; שם ו׳ ע״א: אחזיק להורדי (להורדי) אחזיק לכשורי.</p>","notation":["ז׳"]},"36695":{"h":"הוּדְרָנָא","r":"KRU05690","alt":[],"source":"krupnik","glosses":[{"text":"circle","label":""}],"html":"<p>עיגול circle  פס׳ ע״ו ע״א: דהדר הודרניה.</p>","notation":["ז׳"]},"36696":{"h":"הוה","r":"KRU05691","alt":[],"source":"krupnik","glosses":[{"text":"to dispose of oneself","label":""}],"html":"<p>עמד מצד עצמו to dispose of oneself  כתו׳ מ׳ ע״ב: במהוה עצמה דכתוב מדבר.</p>","notation":["Used in: הִוָּה עַצְמוֹ","Source marks no qal form"]},"36697":{"h":"הוֹהֲרָא","r":"KRU05692","alt":[],"source":"krupnik","glosses":[{"text":"net","label":""}],"html":"<p>רשת net  ירוש׳ מו״ק פ״ב פ״א ע״ב: הוהרא שרי וכו׳ לצוד בה דגים.</p>","notation":["ז׳"]},"36698":{"h":"הַוְועָדָה","r":"KRU05694","alt":[],"source":"krupnik","glosses":[{"text":"admonition","label":""}],"html":"<p>התראה ואזהרה admonition  ירוש׳ ב״ק פ״ד ד׳ ע״ב: תמה וכו׳ הוועדה.</p>","notation":["נ׳"]},"36699":{"h":"הֶוְותִּיאוֹס","r":"KRU05695","alt":["הֶוְותֵּיוֹס"],"source":"krupnik","glosses":[{"text":"immediately after","label":""}],"html":"<p>תיכף ומיד, אחרי ירוש׳ נדה immediately after  פ״ב מ״ט ע״ד: בין הוותיאוס בין שלא הוותיוס.</p>","notation":[]},"36700":{"h":"הֲוָיָה","r":"KRU05697","alt":[],"source":"krupnik","glosses":[{"text":"existence","label":"1"},{"text":"the legal status of marriage","label":"2"},{"text":"discussion, argument","label":"3"}],"html":"<p>1 מציאות existence  ב״ב ק״כ ע״א: ותהיינה הויה אחת לכולן.\n2 חיתון the legal status of marriage  כתו׳ כ״ז ע״ב: מקיש הויה ליציאה.\n3 משא ומתן של הלכה discussion, argument  סוכה כ״ח ע״א: הויות דאביי ורבא.</p>","notation":["נ׳"]},"36701":{"h":"הַוְיָנָא","r":"KRU05698","alt":[],"source":"krupnik","glosses":[{"text":"intelligence","label":""}],"html":"<p>תבונה intelligence  תרג׳ מש׳ כ״ח ט״ז (תבונות): הוינא.</p>","notation":["ז׳"]},"36702":{"h":"הוֹכֵיחַ","r":"KRU05699","alt":[],"source":"krupnik","glosses":[{"text":"evidence","label":""}],"html":"<p>ראיה evidence  ירוש׳ דמ׳ פ״ב כ״ב ע״ג: ונעשה אותו הגר הוכיח לכל הגרים.</p>","notation":["ז׳"]},"36703":{"h":"הוֹלָכָה","r":"KRU05700","alt":[],"source":"krupnik","glosses":[{"text":"leading, carrying","label":""}],"html":"<p>נשיאה והעברה ממקום למקום leading, carrying  גיט׳ ס״ג ע״א: שאין שליחות לקבלה וגמר ונתן לשם הולכה.</p>","notation":["נ׳"]},"36704":{"h":"הוּמְהוֹם","r":"KRU05701","alt":[],"source":"krupnik","glosses":[{"text":"oath","label":""}],"html":"<p>שבועה oath  תרג׳ ירוש׳ דב׳ כ״ז ט״ו: הומהום.</p>","notation":["ז׳"]},"36705":{"h":"הוֹמוֹנְיָא","r":"KRU05702","alt":[],"source":"krupnik","glosses":[{"text":"union","label":""}],"html":"<p>חטיבה, יד אחת union  איכ״ר פתיחתא (ר׳ אלכנדרי א׳): נעשו כולן הומוניא.</p>","notation":["נ׳"]},"36706":{"h":"הוּמַנְיָא","r":"KRU05703","alt":[],"source":"krupnik","glosses":[{"text":"name of a town in Babylonia","label":""}],"html":"<p>שם מקום בבבל name of a town in Babylonia  קיד׳ ע״ב ע״ב: כגון הומניא לפום נהרא.</p>","notation":[]},"36707":{"h":"הוּנָא","r":"KRU05704","alt":[],"source":"krupnik","glosses":[{"text":"name of Amoraim","label":""}],"html":"<p>שם אמוראים name of Amoraim  כת׳ ק״ו ע״א: מתיבתא דר׳ הונא.</p>","notation":[]},"36708":{"h":"הוּנְגְטֵיס","r":"KRU05706","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  במ״ר ד׳: הונגטיס הגמון. </p>","notation":["שם איש"]},"36709":{"h":"הוּנְגְּרָאָה","r":"KRU05707","alt":[],"source":"krupnik","glosses":[{"text":"inhabitant of Hagra","label":""}],"html":"<p>יושב ארץ הגר inhabitant of Hagra  תרג׳ תהל׳ פ״ג ז׳ (והגרים): והונגראי.</p>","notation":["ת׳"]},"36710":{"h":"הוֹנְדְּקָס","r":"KRU05708","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ שבת פט״ז ט״ו ע״ד: רבי הונדקס.</p>","notation":[]},"36711":{"h":"הונים","r":"KRU05710","alt":[],"source":"krupnik","glosses":[{"text":"ass","label":""}],"html":"<p>חמור ass  ירוש׳ שבת פ״ו ח׳ ע״ג: הונים קטמין.</p>","notation":["ז׳","Source emendation: הוֹנוֹס"]},"36712":{"h":"הוּפְכָא","r":"KRU05711","alt":[],"source":"krupnik","glosses":[{"text":"perverseness","label":""}],"html":"<p>תהפוכות perverseness  תרג׳ מש׳ ב׳ י״ד (בתהפוכות): בהופכא.</p>","notation":["ז׳"]},"36713":{"h":"הוֹפָעָה","r":"KRU05712","alt":["הוֹפָעוּתָא"],"source":"krupnik","glosses":[{"text":"appearance","label":""}],"html":"<p>התגלות appearance  ספרי ברכה שמ״ג: ארבע הופעות הן ראשונה במצרים וכו׳; תרג׳ שופ׳ ה׳ ד׳: הופעותא.</p>","notation":[]},"36714":{"h":"הוּפְקָנָה","r":"KRU05713","alt":[],"source":"krupnik","glosses":[{"text":"sufficiency","label":""}],"html":"<p>די הסיפוק sufficiency  תרג׳ מש׳ כ״ה ט״ז (אכול דיך): אכול הופקנה.</p>","notation":["ז׳"]},"36715":{"h":"הוּץ","r":"KRU05714","alt":["הוּצָא"],"source":"krupnik","glosses":[{"text":"palm-leaf","label":""}],"html":"<p>עלה התמר palm-leaf  תוס׳ שב׳ ח׳ י׳: הוצין כדי לעשות אוזן לכפיפה; ב״ב ד׳ ע״א: בהוצא ודפנא.</p>","notation":[]},"36716":{"h":"הוּצָא","r":"KRU05715","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  ירוש׳ נדר׳ פ״ט מ״ב ע״ג: יהודה איש הוצא.</p>","notation":[]},"36717":{"h":"הוֹצָאָה","r":"KRU05716","alt":[],"source":"krupnik","glosses":[{"text":"carrying out","label":"1"},{"text":"sprouting","label":"2"},{"text":"going out","label":"3"},{"text":"expenditure, outlay","label":"4"}],"html":"<p>1 העברה ממקום למקום carrying out  מגי׳ ג׳ ע״ב: הוצאת המת.\n2 צמיחה sprouting  שבי׳ פ״ה ל״ה ע״ד: מהוצאת עלין.\n3 יציאה going out  ב״ר פע״ב: הוצאה משל בעל הבית והכנסה משל פועל.\n4 ממון היוצא לצרכים שונים expenditure, outlay  שבת קי״ז ע״ב: לעולם ישכים אדם להוצאת שבת.</p>","notation":["נ׳"]},"36718":{"h":"הוֹצָאַת נֶפֶשׁ","r":"KRU05717","alt":[],"source":"krupnik","glosses":[{"text":"escape of life","label":""}],"html":"<p>יציאת נשמה escape of life  חול׳ ל״ח ע״א: בהמה דקה שפשטה ידה ולא החזירה פסולה שאינה אלא הוצאת נפש.</p>","notation":[]},"36719":{"h":"הוּצָל","r":"KRU05718","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  מגי׳ ה׳ ע״ב: הוצל דבית בנימין.</p>","notation":[]},"36720":{"h":"הוֹצֶן","r":"KRU05719","alt":[],"source":"krupnik","glosses":[{"text":"stalk","label":""}],"html":"<p>קנה, גבעול stalk  סוכה י״ב ע״ב: הוצני פשתן.</p>","notation":["ז׳"]},"36721":{"h":"הוֹקָעָה","r":"KRU05720","alt":[],"source":"krupnik","glosses":[{"text":"hanging","label":""}],"html":"<p>תליה hanging  סנה׳ ל״ד ע״ב: מנין להוקעה שהיא תלייה וכו׳.</p>","notation":["נ׳"]},"36722":{"h":"הוֹרָאָה","r":"KRU05721","alt":[],"source":"krupnik","glosses":[{"text":"decision","label":""}],"html":"<p>פסק הלכה decision  פס׳ ג׳ ע״ב: מורה הוראה.</p>","notation":["נ׳"]},"36723":{"h":"הוּרְדָּא","r":"KRU05722","alt":[],"source":"krupnik","glosses":[{"text":"beam for ornament","label":""}],"html":"<p>קורה לקישוט beam for ornament  ב״ב ו׳ ע״ב: אחזיק להורדי.</p>","notation":["ז׳"]},"36724":{"h":"הוֹרָדָה","r":"KRU05723","alt":[],"source":"krupnik","glosses":[{"text":"letting down","label":""}],"html":"<p>העברה מלמעלה למטה letting down  ירוש׳ סוטה פ״ט כ״ד ע״א: משעת הורדה.</p>","notation":["נ׳"]},"36725":{"h":"הוֹרְדּוֹס","r":"KRU05724","alt":[],"source":"krupnik","glosses":[{"text":"Herod, the king","label":""}],"html":"<p>המלך Herod, the king  ב״ב ג׳ ע״ב: הורדוס עבדא דבית חשמונאי הוה.</p>","notation":[]},"36726":{"h":"הוֹרָה","r":"KRU05725","alt":[],"source":"krupnik","glosses":[{"text":"conception","label":""}],"html":"<p>יצירת הולד conception  ירוש׳ יבמ׳ פי״א י״א ע״ד: גר שהיתה הורתו שלא בקדושה ולידתו בקדושה.</p>","notation":["נ׳"]},"36727":{"h":"הוֹרְכִּינָס","r":"KRU05728","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ר״ה כ״ה ע״א: ר׳ דוסא בן הורכינס. </p>","notation":["שם איש"]},"36728":{"h":"הוֹרְקִינָס","r":"KRU05729","alt":["הוֹרְקְנוֹס"],"source":"krupnik","glosses":[{"text":"names of men","label":""}],"html":"<p>שמות אנשים names of men  תוס׳ כל׳ ב״ב ד׳ י״ד: ר׳ דוסא בן הורקינוס; ב״ק פ״ב ע״ב: כשצרו בית חשמונאי זה על זה היה הורקנוס מבפנים ואריסטובלס מבחוץ.</p>","notation":[]},"36729":{"h":"הוֹשָׁטָה","r":"KRU05730","alt":[],"source":"krupnik","glosses":[{"text":"reaching over","label":""}],"html":"<p>שליחת היד reaching over  ירוש׳ שבת פ״ז י׳ ע״ב: ולמה לא תנינן הושטה עמהון.</p>","notation":["נ׳"]},"36730":{"h":"הוֹשָׁעָה","r":"KRU05731","alt":[],"source":"krupnik","glosses":[{"text":"relief, delivery","label":""}],"html":"<p>ישועה וגאולה relief, delivery  ילק׳ במ׳ תשכ״ה: הושעה וטובה.</p>","notation":["נ׳"]},"36731":{"h":"הוֹשַׁעְיָא","r":"KRU05732","alt":["הוֹשַׁעְיָה"],"source":"krupnik","glosses":[{"text":"names of Tannaim and Amoraim","label":""}],"html":"<p>שמות תנאים ואמוראים names of Tannaim and Amoraim  ירוש׳ יבמ׳ פ״ג ד׳ ע״ד: ר׳ הושעיה; בר׳ פ״ב ה׳ ע״ב: ר׳ הושעיא רובא.</p>","notation":[]},"36732":{"h":"הוֹשַׁעְנָא","r":"KRU05733","alt":[],"source":"krupnik","glosses":[{"text":"willow and myrtle carried together with the lulab","label":""}],"html":"<p>הערבה וההדס שנושאים עם הלולב willow and myrtle carried together with the lulab  סוכה ל״ז ע״א וע״ב: כי גדליתו הושענא. ועי׳ יוֹם הוֹשַׁעְנָא.</p>","notation":["נ׳"]},"36733":{"h":"הַזָּאָה","r":"KRU05734","alt":[],"source":"krupnik","glosses":[{"text":"sprinkling","label":""}],"html":"<p>זריקת דם וכדומה sprinkling  יומא מ״ב ע״ב: הזאת מימיה וכו׳ והזאת דמה וכו׳.</p>","notation":["נ׳"]},"36734":{"h":"הֲזָדָה","r":"KRU05735","alt":[],"source":"krupnik","glosses":[{"text":"wilfulness","label":""}],"html":"<p>מעשה זדון wilfulness  סנה׳ ט״ז ע״א: הזדה הזדה מזקן ממרא.</p>","notation":["נ׳"]},"36735":{"h":"הֶזֵיק","r":"KRU05737","alt":["הֶזֵיקָא"],"source":"krupnik","glosses":[{"text":"damage, injury","label":""}],"html":"<p>נזק והפסד damage, injury  ב״ק ב׳ ע״ב: רגל הזיקה מצוי; פס׳ ח׳ ע״ב: דשכיח הזיקא.</p>","notation":[]},"36736":{"h":"הַזְכָּרָה","r":"KRU05738","alt":[],"source":"krupnik","glosses":[{"text":"notice","label":"1"},{"text":"the insertion of a reference to rain in the Prayer","label":"2"},{"text":"the Tetragrammaton","label":"3"}],"html":"<p>1 הודעה notice  כתו׳ ק״ד ע״א: בעל חוב גובה שלא בהזכרה.\n2 זכר לענין גשמים בתפלה the insertion of a reference to rain in the Prayer  תענ׳ ד׳ ע״ב: שאלה והזכרה.\n3 השם בן ארבע אותיות the Tetragrammaton  ירוש׳ בר׳ פ״ב ח׳ ע״א: שמונה עשרה הזכרות שכתוב בהבו לה׳ בני אלים.</p>","notation":["נ׳"]},"36737":{"h":"הֲזָמָה","r":"KRU05739","alt":[],"source":"krupnik","glosses":[{"text":"the refutation of witnesses by proving an alibi","label":""}],"html":"<p>הוכחת שקרות העדים ע״י טענת עמנו הייתם the refutation of witnesses by proving an alibi  מכות ב׳ ע״א: היאך אתם מעידין שהרי באותו היום אתם הייתם עמנו במקום פלוני הרי אלו זוממין וכו׳ שאין עושין בהן דין הזמה כל עיקר.</p>","notation":["נ׳"]},"36738":{"h":"הַזְמָנָא","r":"KRU05740","alt":[],"source":"krupnik","glosses":[{"text":"summons","label":""}],"html":"<p>קריאה לדין summons  קיד׳ ע׳ ע״א: פיתקא דהזמנא.</p>","notation":["ז׳"]},"36739":{"h":"הַזְמָנָה","r":"KRU05741","alt":[],"source":"krupnik","glosses":[{"text":"designation, preparation","label":""}],"html":"<p>קביעה מלכתחלה designation, preparation  סנה׳ מ״ז ע״ב: הזמנה מילתא.</p>","notation":["נ׳"]},"36740":{"h":"הֶזֵק","r":"KRU05743","alt":[],"source":"krupnik","glosses":[{"text":"damage","label":""}],"html":"<p>הפסד damage  תוס׳ פאה ב׳ כ׳: אם היה הזקו מרובה.</p>","notation":["ז׳"]},"36741":{"h":"הֶחְלֵט","r":"KRU05744","alt":[],"source":"krupnik","glosses":[{"text":"final decision","label":""}],"html":"<p>הכרעה מוחלטת final decision  נגע׳ פ״א מ״ג: מתוך הסגר או מתוך החלט.</p>","notation":["ז׳"]},"36742":{"h":"הַחְלָטָה","r":"KRU05745","alt":[],"source":"krupnik","glosses":[{"text":"putting flour into hot water","label":""}],"html":"<p>מירוס קמח בחמין putting flour into hot water  פסח׳ ל״ז ע״ב: החלטה מי גלשים על קמח.</p>","notation":["נ׳"]},"36743":{"h":"הֲטָבָה","r":"KRU05747","alt":[],"source":"krupnik","glosses":[{"text":"doing good","label":"1"},{"text":"preparing","label":"2"}],"html":"<p>1 גרם טובה doing good  שבוע׳ כ״ז ע״א: הטבת אחרים הרעת אחרים.\n2 הכנה ותקון preparing  ירוש׳ פסח׳ פ״ה ל״א ע״ד: הטבת נרות וכו׳ הטבת קטרת.</p>","notation":["נ׳"]},"36744":{"h":"הַטְבָּלָה","r":"KRU05748","alt":[],"source":"krupnik","glosses":[{"text":"immersion","label":""}],"html":"<p>טבילת כלים במים immersion  ביצה י״ח ע״א: נגזור השקה אטו הטבלה.</p>","notation":["נ׳"]},"36745":{"h":"הִטּוּי","r":"KRU05749","alt":[],"source":"krupnik","glosses":[{"text":"inclination, sliding","label":""}],"html":"<p>נטיה וכפיפה inclination, sliding  ביצה ט׳ ע״א: הטוי סולם.</p>","notation":["ז׳"]},"36746":{"h":"הֲטוּלִים","r":"KRU05750","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  מנח׳ פ״ח מ״ו: קרותים והטולים אלפא ליין.</p>","notation":[]},"36747":{"h":"הֶטֵחַ","r":"KRU05751","alt":[],"source":"krupnik","glosses":[{"text":"plaster","label":""}],"html":"<p>טיח plaster  תוס׳ אהל׳ ז׳ ד׳: אם יכול הטחן.</p>","notation":["ז׳"]},"36748":{"h":"הֲטָחָה","r":"KRU05752","alt":[],"source":"krupnik","glosses":[{"text":"contusion","label":""}],"html":"<p>הכאה contusion  ירוש׳ ב״ק פ״ג ג׳ ע״ג: אם כדרך הטחה הטיח.</p>","notation":["נ׳"]},"36749":{"h":"הַטָּיָיה","r":"KRU05753","alt":[],"source":"krupnik","glosses":[{"text":"being inclined, i.e. giving a verdict according to the majority","label":"1"},{"text":"perversion (of justice)","label":"2"},{"text":"performing coition with a virgin without causing a bleeding","label":"3"}],"html":"<p>1 נטיה being inclined, i.e. giving a verdict according to the majority  סנה׳ פ״א מ״ו: לא כהטייתך לטובה הטייתך לרעה.\n2 עוות הדין perversion (of justice)  סוטה מ״ז ע״ב: השוחד והטיית משפט.\n3 בעילת בתולה בלי הוצאת דם בתולים performing coition with a virgin without causing a bleeding  כת׳ ו׳ ע״ב: יש בקיאין בהטייה.</p>","notation":["נ׳"]},"36750":{"h":"הטליס","r":"KRU05754","alt":["הַטְלִיס"],"source":"krupnik","glosses":[{"text":"single","label":""}],"html":"<p>בגפו single  ב״ר פי״ט: שמא אני מתה ואתה יושב לך הטלים; שס פפ״ז: הטליס חייך שאני מגרה בך את הדוב.</p>","notation":[]},"36751":{"h":"הַטְמָנָה","r":"KRU05756","alt":[],"source":"krupnik","glosses":[{"text":"preserving a dish in a warm place (for the Sabbath)","label":""}],"html":"<p>שמירה בחום preserving a dish in a warm place (for the Sabbath)  שבת ל״ט ע״ב: הטמנה בדבר המוסיף הבל.</p>","notation":["נ׳"]},"36752":{"h":"הַטָּפָה","r":"KRU05757","alt":[],"source":"krupnik","glosses":[{"text":"prophetic speech","label":""}],"html":"<p>הדיבור הנבואי prophetic speech  שהש״ר ג׳ ד׳: חזון נבואה הטפה וכו׳.</p>","notation":["נ׳"]},"36753":{"h":"הֶטְרֵחַ","r":"KRU05758","alt":[],"source":"krupnik","glosses":[{"text":"taking pains with preparation","label":""}],"html":"<p>הכנה בטירחה יתרה taking pains with preparation  קה״ר ט׳ ח׳: כלום יש סעודה שאין בה הטרח.</p>","notation":["ז׳"]},"36754":{"h":"הִטְרִיוֹת","r":"KRU05759","alt":[],"source":"krupnik","glosses":[{"text":"preserved gourds","label":""}],"html":"<p>אבטיחים כבושים preserved gourds  נדר׳ מ״ט ע״א: הטריות רכות.</p>","notation":["נ״ר"]},"36755":{"h":"הֵ״י","r":"KRU05762","alt":[],"source":"krupnik","glosses":[{"text":"name of the fifth letter of the Alphabet","label":""}],"html":"<p>שם האות החמישית באלפבית name of the fifth letter of the Alphabet  מנ׳ ל״ז ע״א: מידכה בה״י כהה.</p>","notation":[]},"36756":{"h":"הֵי","r":"KRU05763","alt":[],"source":"krupnik","glosses":[{"text":"behold, here is","label":"1"},{"text":"which?","label":"2"},{"text":"where?","label":"3"}],"html":"<p>1  behold, here is  סוכה נ״ה ע״א: הי לך מצה.\n2  which?  חול׳ מ״ט ע״ב: לא ידענא הי מינייהו.\n3 איה, היכן where?  בר׳ ל״א ע״א: הי תורה והי מצוה דמגני עלן.</p>","notation":[]},"36757":{"h":"הֵיאַךְ","r":"KRU05764","alt":[],"source":"krupnik","glosses":[{"text":"how?","label":""}],"html":"<p>מח״ש, כיצד how?  ע״ז פ״ב מ״ה: היאך אתה קורא.</p>","notation":[]},"36758":{"h":"הֵיגֶה","r":"KRU05765","alt":["הֵיגְתָא"],"source":"krupnik","glosses":[{"text":"alhagi","label":""}],"html":"<p>מין שיח קוצים alhagi  שב׳ ק״י ע״ב: חרגונא דהיגתא רומיתא; ילק׳ יש׳ ש״ב: היגין וקוצים.</p>","notation":["ז׳"]},"36759":{"h":"הֵידָא","r":"KRU05766","alt":[],"source":"krupnik","glosses":[{"text":"which?","label":""}],"html":"<p>איזה which?  קה״ר ט׳ י״א: הידא מלכות קמת בהון.</p>","notation":["מה״ש"]},"36760":{"h":"הִידוּס","r":"KRU05768","alt":[],"source":"krupnik","glosses":[{"text":"upturning, scratching (of chickens)","label":""}],"html":"<p>ניקור וחטיטה upturning, scratching (of chickens)  ב״ק י״ח ע״ב: הידוס אינו מועד.</p>","notation":["ז׳"]},"36761":{"h":"הִידוּק","r":"KRU05769","alt":[],"source":"krupnik","glosses":[{"text":"stopper","label":""}],"html":"<p>סתימה בפי כלי stopper  ירוש׳ פסח׳ פ״ג ל׳ ע״א: הידוק קרויא וכרויה.</p>","notation":["ז׳"]},"36762":{"h":"הִידוּר","r":"KRU05770","alt":[],"source":"krupnik","glosses":[{"text":"paying respect","label":"1"},{"text":"adorning","label":"2"}],"html":"<p>1 כיבוד paying respect  ספרא קדוש׳ פ׳: איזהו הידור לא ישב במקומו וכו׳.\n2 קישוט adorning  ב״ק ט׳ ע״ב: בהידור מצוה עד שליש.</p>","notation":["ז׳"]},"36763":{"h":"הֵידֵין","r":"KRU05771","alt":[],"source":"krupnik","glosses":[{"text":"then","label":""}],"html":"<p>אז then  תרג׳ מש׳ א׳ כ״ח (אז): הידין.</p>","notation":["תה״פ"]},"36764":{"h":"הֵיה","r":"KRU05772","alt":[],"source":"krupnik","glosses":[{"text":"the fifth letter of the Alphabet","label":""}],"html":"<p>אות חמישית באלפבית the fifth letter of the Alphabet  שבת ק״ג ע״ב: היהין חיתין וכו׳.</p>","notation":["ז׳"]},"36765":{"h":"הֶיזֵיק","r":"KRU05773","alt":["הֶיזֵיקָא"],"source":"krupnik","glosses":[{"text":"damage","label":""}],"html":"<p>נזק, הפסד damage  ב״ק ב׳ ע״ב: שן יש הנאה להיזיקה; ב״ק ה׳ ע״א: היזיקא דמינכר.</p>","notation":[]},"36766":{"h":"הִיזְמָא","r":"KRU05774","alt":["הִיזְמְתָא"],"source":"krupnik","glosses":[{"text":"cockshead","label":""}],"html":"<p>מין ירק קוצי cockshead  כת׳ ע״ז ע״ב: שכר של היזמי; עיר׳ כ״ח ע״ב: דקטלינן לה להיזמתא.</p>","notation":[]},"36767":{"h":"הֶיזֵק","r":"KRU05775","alt":[],"source":"krupnik","glosses":[{"text":"damage","label":""}],"html":"<p>נזק והפסד damage  גיט׳ נ״ג ע״א: היזק שאינו ניכר.</p>","notation":["ז׳"]},"36768":{"h":"הִיטְנֵי","r":"KRU05776","alt":[],"source":"krupnik","glosses":[{"text":"reeds","label":""}],"html":"<p>קנים reeds  יומא ע״ח ע״ב: ר׳ יהודה נפיק בדהיטני.</p>","notation":["ז״ר"]},"36769":{"h":"הַיי","r":"KRU05777","alt":[],"source":"krupnik","glosses":[{"text":"this","label":""}],"html":"<p>זה, זאת this  ירוש׳ כת׳ פי״ב ל״ה ע״א: היי שיניך מה היא עבידא.</p>","notation":["מה״ג"]},"36770":{"h":"הַיי²","r":"KRU05778","alt":["הַיְיא"],"source":"krupnik","glosses":[{"text":"which?","label":""}],"html":"<p>איזה? which?  כת׳ י״ב ע״א: אהייא; ירוש׳ שם פ״ז ל״א ע״ג: בהיי דא מתניתא.</p>","notation":[]},"36771":{"h":"הַיָיא","r":"KRU05779","alt":[],"source":"krupnik","glosses":[{"text":"quickly","label":"1"},{"text":"go on!","label":"2"}],"html":"<p>1  quickly  שבת קל״ד ע״ב: סליק ביה בשרא הייא.\n2  go on!  פסח׳ קי״ב: נזהא דארבא הליוני הייא וכו׳.</p>","notation":[]},"36772":{"h":"הַיְידָּא","r":"KRU05780","alt":["הַיְידָּה","הַיְידִּי","הַיְידֵּינוּ","הַיְידָּלוֹן","הַיְידֵּן","הַיְידְּנוּ"],"source":"krupnik","glosses":[{"text":"this; which?","label":""}],"html":"<p>ומה״ש, זה, איזה this; which?  ירוש׳ דמ׳ פ״א כ״ב ע״ב: היידה מחלוקת; שבת פ״ז י׳ ע״ג: היידא משום נטילת נשמה; ב״ר פפ״ד: היידי ליה; פס׳ פ״ה ל״ב ע״ג: והיידינו לשמו פטור; בכורים פ״ב ס״ד ע״ג: והיידלון חמשים; שבת פי״ט י״ז ע״ב: היידן ר׳ יוסי; עיר׳ פ״ה כ״ב ע״ג: היידנו אמצעי.</p>","notation":[]},"36773":{"h":"הַיְינוּ","r":"KRU05781","alt":[],"source":"krupnik","glosses":[{"text":"it is this, it is the same","label":""}],"html":"<p>זהו it is this, it is the same  בר׳ ב׳ ע״ב: חכמים היינו ר׳ מאיר.</p>","notation":["מה״ג"]},"36774":{"h":"הַיְינוּ הַךְ","r":"KRU05782","alt":[],"source":"krupnik","glosses":[{"text":"it is the same case","label":""}],"html":"<p>ענין אחד הוא it is the same case  יבמ׳ כ״ג ע״ב: היינו הך.</p>","notation":[]},"36775":{"h":"הֵיךְ","r":"KRU05783","alt":[],"source":"krupnik","glosses":[{"text":"how?","label":""}],"html":"<p>כיצד how?  ירוש׳ עיר׳ פ״א י״ט ע״ב: היך עבידא.</p>","notation":["מה״ש"]},"36776":{"h":"הֵיךְ מָה","r":"KRU05784","alt":[],"source":"krupnik","glosses":[{"text":"as","label":""}],"html":"<p>כמו as  ירוש׳ סוכה פ״ג נ״ד ע״א: היך מה דאמרת.</p>","notation":[]},"36777":{"h":"הֵיכָא","r":"KRU05785","alt":[],"source":"krupnik","glosses":[{"text":"where?","label":"1"},{"text":"where","label":"2"}],"html":"<p>1  where?  בר׳ ב׳ ע״א: תנא היכא קאי.\n2 מח״י, במקום שם where  יומא ב׳ ע״ב: היכא דליכא.</p>","notation":[]},"36778":{"h":"הֵיכְדֵּין","r":"KRU05786","alt":[],"source":"krupnik","glosses":[{"text":"even so","label":"1"},{"text":"how","label":"2"}],"html":"<p>1  even so  תרג׳ יב״ע ו׳ ל׳: כהלכת חטייתא היכדין הלכת אשמא.\n2  how  תרג׳ תהל׳ ע״ג י״א (איכה): היכדין.</p>","notation":[]},"36779":{"h":"הֵיכִי","r":"KRU05787","alt":["הֵיכִין"],"source":"krupnik","glosses":[{"text":"how?","label":""}],"html":"<p>כיצד how?  בר׳ ד׳ ע״ב: היכי מצי סמיך; נדר׳ נ״א ע״ב: היכין משמע.</p>","notation":[]},"36780":{"h":"הֵיכִי דְמֵי","r":"KRU05788","alt":[],"source":"krupnik","glosses":[{"text":"in what case?","label":""}],"html":"<p>באיזה אופן in what case?  שבת ד׳ ע״א: היכי דמי אילמא וכו׳.</p>","notation":[]},"36781":{"h":"הֶיכֵּירָא","r":"KRU05789","alt":[],"source":"krupnik","glosses":[{"text":"sign, mark","label":""}],"html":"<p>סימן ורושם sign, mark  יומא ב׳ ע״א: דליהוי לה היכירא.</p>","notation":["ז׳"]},"36782":{"h":"הֵיכְמָא","r":"KRU05790","alt":["הֵיכְמָה"],"source":"krupnik","glosses":[{"text":"as","label":""}],"html":"<p>כמו as  תרג׳ יב״ע בר׳ כ״א א׳ (כאשר אמר) היכמא דאמר; ירוש׳ עיר׳ פ״א י״ט ע״ב: היכמה דתימר תמן.</p>","notation":[]},"36783":{"h":"הֵיכָן","r":"KRU05791","alt":[],"source":"krupnik","glosses":[{"text":"where?","label":"1"},{"text":"there","label":"2"}],"html":"<p>1  where?  סוכה כ״ג ע״א: היכן סוכתך.\n2 מקום שם there  מדר׳ תה׳ ד׳: היכן שהיה הקב״ה רואה מקום עמוק היה נותן הר.</p>","notation":[]},"36784":{"h":"הֵיכְנָא","r":"KRU05792","alt":[],"source":"krupnik","glosses":[{"text":"thus","label":"1"},{"text":"oh, how","label":"2"}],"html":"<p>1 כן thus  תרג׳ מש׳ ז׳ ט״ו (על כן): מטול היכנא.\n2 מה״ק, איכה! oh, how  שם ה׳ י״ב (איך שנאתי מוסר): היכנא סניית מרדותא.</p>","notation":["מה״י"]},"36785":{"h":"הֶיכֵּר","r":"KRU05793","alt":["הֶיכֵּרָא"],"source":"krupnik","glosses":[{"text":"mark, sign","label":""}],"html":"<p>סימן ורושם mark, sign  עיר׳ י״א ע״ב: צורת הפתח צריכה היכר ציר; זבח׳ כ״א ע״ב: בי תרי היכרי הוי צבדי.</p>","notation":[]},"36786":{"h":"הִילָא","r":"KRU05794","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ יומא פ״ו מ״ג ע״ג: ר׳ הילא אמר.</p>","notation":[]},"36787":{"h":"הִילוּךְ","r":"KRU05795","alt":["הִילוּכָא"],"source":"krupnik","glosses":[{"text":"walking","label":"1"}],"html":"<p>1 הליכה walking  כת׳ קי״א ע״א: שליש בעמידה שליש בישיבה שליש בהילוך; שבת קמ״ח ע״א: קא מפשי בהילוכא.\n2 עי׳ הוֹלָכָה. זבח׳ ט״ו ע״ב: הילוך שצריך להלך. ועי׳ הִלּוּךְ. </p>","notation":[]},"36788":{"h":"הִילוּלָא","r":"KRU05797","alt":[],"source":"krupnik","glosses":[{"text":"wedding feast","label":""}],"html":"<p> wedding feast  בר׳ ל״א ע״ב: עביד הילולא לבריה.</p>","notation":["ז׳"]},"36789":{"h":"הַיְלֵין","r":"KRU05798","alt":[],"source":"krupnik","glosses":[{"text":"those","label":""}],"html":"<p>הללו those  ויק״ר פכ״ה: והילין תאיניא.</p>","notation":["מה״ג"]},"36790":{"h":"הֵילָךְ","r":"KRU05801","alt":[],"source":"krupnik","glosses":[{"text":"here it is","label":"1"}],"html":"<p>1 הרכבה מן הֵא לָךְ, הרי here it is  סוכה פ״ה מ״ז: הילך מצה הילך חמץ.</p>","notation":[]},"36791":{"h":"הֵילָךְ וְהֵילָךְ","r":"KRU05802","alt":[],"source":"krupnik","glosses":[{"text":"here and there","label":""}],"html":"<p>הֵנה והֵנה here and there  תמי׳ פ״ה ה״ה: יפנה את הגחלים הילך והילך.</p>","notation":["תה״פ"]},"36792":{"h":"הִילְכָךְ","r":"KRU05803","alt":[],"source":"krupnik","glosses":[{"text":"therefore","label":""}],"html":"<p>על כן, לפיכך therefore  מגי׳ כ״א ע״ב: הילכך נימרינהו לתרווייהו.</p>","notation":["מה״ח"]},"36793":{"h":"הִילְמִי","r":"KRU05807","alt":[],"source":"krupnik","glosses":[{"text":"brine (for pickling)","label":""}],"html":"<p>מי מלח brine (for pickling)  שבת ק״ח ע״א וע״ב: אין עושין הילמי בשבת.</p>","notation":["נ׳"]},"36794":{"h":"הִילְנִי","r":"KRU05808","alt":[],"source":"krupnik","glosses":[{"text":"go on!","label":"1"},{"text":"name of women","label":"2"}],"html":"<p>1  go on!  פסח׳ קי״ב: נזהא דארבא הילני הייא.\n2 שם נשים name of women  סוכה ב׳ ע״ב: הילני המלכה; ויק״ר סוף פי״ב: ר׳ הילל בר הילני.</p>","notation":[]},"36795":{"h":"הִילְקֵט","r":"KRU05809","alt":[],"source":"krupnik","glosses":[{"text":"pile","label":""}],"html":"<p>תל pile  נזיר ח׳ ע״ב: כמנין הילקטי קיץ.</p>","notation":["ז׳"]},"36796":{"h":"הִילְקְטִי","r":"KRU05810","alt":[],"source":"krupnik","glosses":[{"text":"winding staircase","label":""}],"html":"<p>לול לעלות בו winding staircase  שבת קנ״ז ע״ב: הילקטי קטנה היתה בין שני בתים.</p>","notation":["נ׳"]},"36797":{"h":"הֵימְ־","r":"KRU05811","alt":["הֵימֶךָ","הֵימֶנּוּ","הֵימֶנָּהּ"],"source":"krupnik","glosses":[{"text":"from, of you, him a. s. o.","label":""}],"html":"<p>ממני, ממך וכו׳ from, of you, him a. s. o.  מו״ק פ״ג מ״ה: בטלה הימנו גזרת שבעה: במד״ר פ״ב: אין נאה הימנה; נדר׳ ח׳ ע״א: מודרני הימך; ע״ז נ״ט ע״ב: לא כל הימנך.</p>","notation":["Source marks no qal form"]},"36798":{"h":"הִימוּ","r":"KRU05812","alt":[],"source":"krupnik","glosses":[{"text":"they","label":""}],"html":"<p>הם they  ירוש׳ ב״ב פ״י מ״ב: די הימו.</p>","notation":["מה״ג"]},"36799":{"h":"הִימְיָינָא","r":"KRU05815","alt":[],"source":"krupnik","glosses":[{"text":"girdle","label":""}],"html":"<p>אזור girdle  שבת נ״ט ע״ב: מידי דהוה אאבנט של מלכים וכו׳ הימיינא מאי.</p>","notation":["ז׳"]},"36800":{"h":"הִימְלְטָא","r":"KRU05816","alt":[],"source":"krupnik","glosses":[{"text":"sill","label":""}],"html":"<p>אדן sill  ב״ב ו׳ ע״א: אע״ג דמנח ביה הימלטי.</p>","notation":["ז׳"]},"36801":{"h":"הִימַלְתָּא","r":"KRU05817","alt":[],"source":"krupnik","glosses":[{"text":"preserved ginger","label":""}],"html":"<p>זנגביל כבוש בדבש preserved ginger  יומא פ״א ע״ב: הימלתא.</p>","notation":["נ׳"]},"36802":{"h":"הִימְנוֹן","r":"KRU05819","alt":[],"source":"krupnik","glosses":[{"text":"hymn","label":""}],"html":"<p>שיר ושבחה hymn  שמו״ר פמ״ה: והיו מלאכי השרת באין לומר הימנון לפניו.</p>","notation":["ז׳"]},"36803":{"h":"הֵימָנוּתָא","r":"KRU05820","alt":[],"source":"krupnik","glosses":[{"text":"trust, confidence","label":""}],"html":"<p>אמונה, אמון trust, confidence  ב״מ ט״ו ע״ב: דליקו בהימנותיה.</p>","notation":["נ׳"]},"36804":{"h":"הֵימָנִי","r":"KRU05821","alt":[],"source":"krupnik","glosses":[{"text":"steady","label":""}],"html":"<p>מיושב steady  ילק׳ במ׳ תשע״ו: רוח הימנית וכו׳ קפדנית.</p>","notation":["ת׳"]},"36805":{"h":"הִימְנָק","r":"KRU05822","alt":[],"source":"krupnik","glosses":[{"text":"fork","label":""}],"html":"<p>מין מזלג fork  סוכה ל״ב ע״א: דעביד כהימנק.</p>","notation":["ז׳"]},"36806":{"h":"הִימַסְיוֹן","r":"KRU05823","alt":[],"source":"krupnik","glosses":[{"text":"amethyst","label":""}],"html":"<p>מין אבן טובה amethyst  ב״ר סוף פל״ח: גד הימסיון.</p>","notation":["ז׳"]},"36807":{"h":"הִין","r":"KRU05824","alt":[],"source":"krupnik","glosses":[{"text":"if","label":"1"},{"text":"yes","label":"2"}],"html":"<p>1  if  ירוש׳ בכורים פ״א ס״ג ע״ד: הין תימר.\n2 הֵן, כן yes  ירוש׳ עיר׳ פ״ג נ״ג ע״ב: ממשמע לאו אתה שומע הין.</p>","notation":[]},"36808":{"h":"הִינָא","r":"KRU05825","alt":[],"source":"krupnik","glosses":[{"text":"a liquid measure","label":"1"},{"text":"half-baked","label":"3"}],"html":"<p>1  a liquid measure  תרג׳ שמ׳ ל׳ כ״ה (הין): הינא.\n2  one | eines ב״ב קס״ד ע״ב: הינא אחת דיגון שתים.\n3 נא, אפוי למחצה half-baked  פס׳ ל״ז ע״א: הינא מצה.</p>","notation":[]},"36809":{"h":"הִינְדְּבִי","r":"KRU05827","alt":[],"source":"krupnik","glosses":[{"text":"endive","label":""}],"html":"<p>מין צמח endive  פסח׳ ל״ט ע״א: עולשין הינדבי.</p>","notation":["נ׳"]},"36810":{"h":"הִינְדָּוָא","r":"KRU05828","alt":["הִינְדְּוָאָה"],"source":"krupnik","glosses":[{"text":"Indian","label":""}],"html":"<p>מארץ הודו Indian  ב״ב ע״ד ע״ב: ר׳ יהודה הינדוא; ע״ז ט״ז: פרזלא הינדואה.</p>","notation":[]},"36811":{"h":"הִינְדְּזָא","r":"KRU05829","alt":[],"source":"krupnik","glosses":[{"text":"calculation of proportions","label":""}],"html":"<p>חשבון מדוייק (ביחס נכון) calculation of proportions  גיט׳ ס׳ ע״ב: ואשקי בהינדזא.</p>","notation":["ז׳"]},"36812":{"h":"הִינְדְּיָא","r":"KRU05830","alt":["הִינְדִּיקִי","הִינְדִּיקְיָא"],"source":"krupnik","glosses":[{"text":"India","label":""}],"html":"<p>ארץ הודו India  תרג׳ אס׳ א׳ א׳ (מהודו): מהינדיא; תרג׳ יב״ע בראש׳ ב׳ י״א (ארץ החוילה): ארע הינדיקי; תרג׳ ירוש׳ שם כ״ה י״ח (מחוילה): מהינדיקיא.</p>","notation":[]},"36813":{"h":"הֵינוּחַ","r":"KRU05831","alt":[],"source":"krupnik","glosses":[{"text":"setting down","label":""}],"html":"<p>הנחה setting down  ב״מ כ״א ע״א: דרך הינוח וכו׳ דרך נפילה.</p>","notation":["ז׳"]},"36814":{"h":"הֵינוּמָא","r":"KRU05832","alt":[],"source":"krupnik","glosses":[{"text":"a curtained litter","label":""}],"html":"<p>אפריון a curtained litter  כת׳ פ״ב מ״א: אם יש עדים שיצאה בהינומא.</p>","notation":["נ׳"]},"36815":{"h":"הִינוּן","r":"KRU05833","alt":[],"source":"krupnik","glosses":[{"text":"those","label":""}],"html":"<p>הם, אותם those  ב״ר סוף פ״ט: הינון אותיות דדין הינון אותיות דדין.</p>","notation":["מה״ג"]},"36816":{"h":"הִינִי","r":"KRU05834","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Babylonia","label":"1"},{"text":"a man’s name","label":"2"}],"html":"<p>1 שם מקום בבבל name of a place in Babylonia  ביצה כ״ה ע״ב: מהיני לשילי.\n2  a man’s name  שבת קמ״ז ע״א: אסי בר היני.</p>","notation":[]},"36817":{"h":"הִינָם","r":"KRU05835","alt":[],"source":"krupnik","glosses":[{"text":"excess","label":""}],"html":"<p>זנות excess  עיר׳ י״ט ע״א: גיהנם גיא שהכל יורדין לה על עסקי הינם.</p>","notation":["ז׳"]},"36818":{"h":"הִינֵץ","r":"KRU05836","alt":[],"source":"krupnik","glosses":[{"text":"a coin","label":""}],"html":"<p>מין מטבע a coin  קיד׳ י״ב ע״ב: שני הינצין.</p>","notation":["ז׳"]},"36819":{"h":"הִינָק","r":"KRU05837","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  פסח׳ ק״א ע״ב: רב הינק.</p>","notation":[]},"36820":{"h":"הֶיסֵב","r":"KRU05838","alt":["הֶיסֵבָּה"],"source":"krupnik","glosses":[{"text":"banqueting (around the table)","label":""}],"html":"<p>ישיבה מסביב לשולחן לסעודה banqueting (around the table)  תוס׳ בר׳ ה׳ ה׳: כי זה צד סדר היסב בזמן שהן שתי מיטות גדול מיסב בראשה של ראשונה וכו׳; בר׳ מ״ו ע״ב: כיצד סדר היסבה וכו׳.</p>","notation":["ז׳"]},"36821":{"h":"הֶיסֵחַ","r":"KRU05839","alt":[],"source":"krupnik","glosses":[{"text":"discarding from the mind, diverted attention","label":""}],"html":"<p>הֶיסֵחַ הַדַּעַת ריחוק והעתקה מן הדעת, שכחה discarding from the mind, diverted attention  סנה׳ צ״ז ע״א: שלשה באין בהיסח הדעת אלו הן משיח מציאה ועקרב.</p>","notation":["ז׳"]},"36822":{"h":"הֶיסֵט","r":"KRU05840","alt":["הֶיסֵיט","הֶיסֵיטָא"],"source":"krupnik","glosses":[{"text":"shaking","label":""}],"html":"<p>נענוע shaking  עיר׳ ל״ה ע״א: היסט מחמת כוחו טמא מחמת רעדה טהור; תרג׳ יב״ע במ׳ י״ט כ״ב (הנוגעת): ויקרב ביה מסאבא ולא בהיסיטא; ירוש׳ סוטה פ״ה כ׳ ע״ב: בקיאין בהיסיטות.</p>","notation":[]},"36823":{"h":"הֶיסֵת","r":"KRU05842","alt":[],"source":"krupnik","glosses":[{"text":"the oath applied, if one who is sued for a debt, denies the latter entirely","label":""}],"html":"<p>שְׁבוּעַת הֶיסֵת שבועה שמטילין על כופר הכל the oath applied, if one who is sued for a debt, denies the latter entirely  שבועות מ׳ ע״ב: מנה לי בידך אין לך בידי פטור אמר רב נחמן ומשביעין אותו שבועת היסת.</p>","notation":["ז׳"]},"36824":{"h":"הֶיפֵר","r":"KRU05843","alt":[],"source":"krupnik","glosses":[{"text":"invalidation","label":""}],"html":"<p>הפרה וביטול invalidation  נדר׳ ע״ה ע״א: היפר נדרים.</p>","notation":["ז׳"]},"36825":{"h":"הֶיקֵם","r":"KRU05846","alt":[],"source":"krupnik","glosses":[{"text":"confirmation","label":""}],"html":"<p>קיום ואישור confirmation  נדר׳ ע״ד ע״א: את שבא לכלל היקם בא לכלל היפר.</p>","notation":["ז׳"]},"36826":{"h":"הֶיקֵף","r":"KRU05847","alt":["הֶיקֵפָא"],"source":"krupnik","glosses":[{"text":"circumference","label":""}],"html":"<p>חוג העיגול circumference  ירוש׳ עיר׳ פ״ז כ״ד ע״ב: היה בו היקף צ״ו טפחים; ב״ק כ׳ ע״ב: היקפא יתירא.</p>","notation":[]},"36827":{"h":"הֶיקֵשׁ","r":"KRU05848","alt":[],"source":"krupnik","glosses":[{"text":"analogy","label":""}],"html":"<p>השואה הגיונית analogy  ירוש׳ פס׳ פ״ו ל״ג ע״א: מהיקש ומקל וחומר ומגזירה שוה.</p>","notation":["ז׳"]},"36828":{"h":"הִירְדּוּף","r":"KRU05849","alt":[],"source":"krupnik","glosses":[{"text":"oleander","label":""}],"html":"<p>מין עץ oleander  פס׳ ל״ט ע״א: ואימא הירדוף.</p>","notation":["ז׳"]},"36829":{"h":"הִירְהוּן","r":"KRU05850","alt":[],"source":"krupnik","glosses":[{"text":"pledge","label":""}],"html":"<p>משכון pledge  ירוש׳ כת׳ פ״ב כ״ו ע״ד: שנייא היא בהירהון.</p>","notation":["ז׳"]},"36830":{"h":"הֶיתֵּיר","r":"KRU05853","alt":["הֶיתֵּירָא","הֶיתֵּר"],"source":"krupnik","glosses":[{"text":"permission","label":""}],"html":"<p>רשות וחירות permission  ירוש׳ יבמ׳ פ״א ב׳ ע״א: להיתירה הראשון; שבת פ״ז ט׳ ע״ד: נדה יש לה היתר לאחר איסורה; גיט׳ מ״א ע״ב: כחא דהיתירא עדיף.</p>","notation":[]},"36831":{"h":"הַךְ","r":"KRU05854","alt":[],"source":"krupnik","glosses":[{"text":"this","label":""}],"html":"<p>זה, זאת this  יומא י״ג ע״א: מיתא הא קיימא הך.</p>","notation":["מה״ג"]},"36832":{"h":"הָכָא","r":"KRU05855","alt":[],"source":"krupnik","glosses":[{"text":"here","label":""}],"html":"<p>כאן here  סנה׳ ה׳ ע״א: מהכא להתם ומהתם להכא.</p>","notation":["תה״פ"]},"36833":{"h":"הַכָּאָה","r":"KRU05856","alt":[],"source":"krupnik","glosses":[{"text":"striking, blow","label":""}],"html":"<p>מכה striking, blow  תנח׳ תזר׳ ט׳: לסבול הכאות; מכו׳ ח׳ ע״ב: הכאה שאין בה שוה פרוטה.</p>","notation":["נ׳"]},"36834":{"h":"הֲכָאכָא","r":"KRU05857","alt":[],"source":"krupnik","glosses":[{"text":"scratch","label":""}],"html":"<p>שריטה scratch  תוס׳ ב״ק ט׳ כ״ח: ר׳ יהודה היה קורא אותה הכאכא.</p>","notation":["ז׳"]},"36835":{"h":"הֶכְחֵישׁ","r":"KRU05860","alt":["הֶכְחֵשׁ"],"source":"krupnik","glosses":[{"text":"contradiction, incongruity of details of legal evidence","label":""}],"html":"<p>סתירה בדברי העדים contradiction, incongruity of details of legal evidence  ירוש׳ יבמ׳ פט״ו ט״ו ע״א: הכחיש עדות בתוך עדות; נזיר פ״ג נ״ב ע״ד: הכחש.</p>","notation":[]},"36836":{"h":"הַכְחָשָׁה","r":"KRU05861","alt":[],"source":"krupnik","glosses":[{"text":"deterioration, emaciation","label":"2"}],"html":"<p>1 כנ״ל. ב״ק ע״ג ע״ב: הכחשה תחלת הזמנה. \n2 רזון ודלדול בשר deterioration, emaciation  שם צ״ב ע״א: הכחשה דהדר הכחשה דלא הדר.</p>","notation":["נ׳"]},"36837":{"h":"הָכִי","r":"KRU05862","alt":[],"source":"krupnik","glosses":[{"text":"so, thus","label":""}],"html":"<p>כן so, thus  בר׳ ב׳ ע״ב: הכי קאמר ליה.</p>","notation":["מה״י"]},"36838":{"h":"הָכִי הַשְׁתָּא","r":"KRU05863","alt":[],"source":"krupnik","glosses":[{"text":"how can you compare these two cases?","label":""}],"html":"<p>מה ענין זה לזה how can you compare these two cases?  סנה׳ מ״א ע״ב: הכי השתא בחקירות אמר אחד איני יודע עדותן בטילה וכו׳ בדיקות אמר אחד מהן איני יודע עדותן קיימת.</p>","notation":[]},"36839":{"h":"הָכִי נַמִּי","r":"KRU05864","alt":[],"source":"krupnik","glosses":[{"text":"likewise","label":""}],"html":"<p>גם כן likewise  חול׳ ב׳ ע״א: אלא מעתה הכל ממירין וכו׳ הכי נמי דלכתחילה הוא.</p>","notation":[]},"36840":{"h":"הָכִין","r":"KRU05866","alt":[],"source":"krupnik","glosses":[{"text":"so","label":"1"}],"html":"<p>1  so  תרג׳ יש׳ כ״א ו׳ (כמו כן ימותון): אוף אינון הכין ימותו.\n2 עי׳ הֲכָנָה. ירוש׳ ביצה פ״א ס׳ ע״א: בהכינה של אמה. </p>","notation":[]},"36841":{"h":"הֲכִינָה","r":"KRU05867","alt":[],"source":"krupnik","glosses":[{"text":"by-name","label":""}],"html":"<p>כנוי by-name  תענ׳ כ׳ ע״ב: ולא קראתי לחבירי בהכינתו.</p>","notation":["נ׳"]},"36842":{"h":"הַכְמָנָה","r":"KRU05869","alt":[],"source":"krupnik","glosses":[{"text":"hiding (the appointment of witnesses to lie in wait)","label":""}],"html":"<p>הסתרת עדים במארב hiding (the appointment of witnesses to lie in wait)  סנה׳ ס״ז ע״א: מסית זה הדיוט להכמנה.</p>","notation":["נ׳"]},"36843":{"h":"הָכֵן","r":"KRU05870","alt":[],"source":"krupnik","glosses":[{"text":"thus","label":""}],"html":"<p> thus  תרג׳ מש׳ כ״ג ז׳ (כן הוא): הכן הוא.</p>","notation":["מה״י"]},"36844":{"h":"הָכֵן²","r":"KRU05871","alt":["הֲכָנָה"],"source":"krupnik","glosses":[{"text":"preparing, designation","label":"1"},{"text":"marking out the road to the city of refuge","label":"2"}],"html":"<p>1 הזמנה, התכוננות preparing, designation  ירוש׳ שבת פ״ג כ׳ ע״ב: אינו בהכנו; ביצה ב׳ ע״ב: משום הכנה.\n2 ציון הדרכים לערי מקלט marking out the road to the city of refuge  מכו׳ י׳ ע״ב: הכנה לדרך.</p>","notation":["ז׳"]},"36845":{"h":"הַכְנָסָה","r":"KRU05872","alt":[],"source":"krupnik","glosses":[{"text":"putting in","label":"1"},{"text":"coming home","label":"2"}],"html":"<p>1 הבאה putting in  יומא נ״ד ע״א: הכנסת כלים לנרתק שלהם.\n2 כניסה הביתה coming home  ב״ר פע״ב: והכנסה משל פועל.</p>","notation":["נ׳"]},"36846":{"h":"הַכְנָסַת אוֹרְחִים","r":"KRU05873","alt":[],"source":"krupnik","glosses":[{"text":"hospitality","label":""}],"html":"<p>קבלת אורחים וכיבודם hospitality  שבת קכ״ז ע״א: גדולה הכנסת אורחים כהשכמת בית המדרש.</p>","notation":[]},"36847":{"h":"הֶכֵּר","r":"KRU05874","alt":["הַכָּרָה","הַכָּרוּת"],"source":"krupnik","glosses":[{"text":"recognition","label":""}],"html":"<p>הבחנה וידיעה על־פי סימן ורושם recognition  ב״ר פפ״ה: ויכירה הסמיך הכר להכר; נדה ח׳ ע״ב: משיודע העובר וכמה הכרת העובר; ירוש׳ נדה פ״ג נ׳ ע״ג: הכרות פניו.</p>","notation":["ז׳"]},"36848":{"h":"הַכְרָזָה","r":"KRU05875","alt":[],"source":"krupnik","glosses":[{"text":"public announcement","label":""}],"html":"<p>הודעה בפומבי public announcement  סנה׳ כ״ו ע״ב: הכרזה בבית דין.</p>","notation":["נ׳"]},"36849":{"h":"הֶכְרֵיעַ","r":"KRU05876","alt":["הֶכְרֵעַ"],"source":"krupnik","glosses":[{"text":"customary additional weight","label":"1"},{"text":"decision as to the junction of a word with the preceding or the following word","label":"2"}],"html":"<p>1 עודף במשקל customary additional weight  כרית׳ ה׳ ע״א: כשהוא שוקל בהכרע הוא שוקל או עין בעין הוא שוקל.\n2 ודאות ע״ד שייכות המלה לרישא או לסיפא דקרא decision as to the junction of a word with the preceding or the following word  יומא נ״ב ע״א: חמש מקראות בתורה אין להם הכרע; ירוש׳ מגי׳ ד׳ ע״ד ע״ד: ויבינו במקרא אלו ההכריעים.</p>","notation":[]},"36850":{"h":"הַכְרָעָה","r":"KRU05877","alt":[],"source":"krupnik","glosses":[{"text":"decision, verdict by a majority of one","label":"3"}],"html":"<p>1 כנ״ל 1. כרית׳ ה׳ ע״א: והקב״ה יודע בהכרעות. \n2 כנ״ל 2. ב״ר פל״ו: ויבינו במקרא אלו ההכרעות. \n3 החלטה לצד מן הצדדים decision, verdict by a majority of one  נזיר נ״ג ע״א: אין הכרעת שלישי מכרעת.</p>","notation":["נ׳"]},"36851":{"h":"הֶכְשֵׁיר","r":"KRU05878","alt":["הֶכְשֵׁירָא"],"source":"krupnik","glosses":[{"text":"fitness, legality","label":"1"},{"text":"finishing","label":"2"}],"html":"<p>1 כשרות fitness, legality  ירוש׳ גיט׳ פ״ג מ״ד ע״ד: מפסולו את למד הכשירו; חול׳ י״ט ע״ב: כי נפקא חיותא בהכשירא קא נפקא.\n2 שכלול finishing  ב״ר פי״ד: הכשירו באור.</p>","notation":[]},"36852":{"h":"הֶכְשֵׁר","r":"KRU05879","alt":[],"source":"krupnik","glosses":[{"text":"causing","label":"1"},{"text":"cause of fitness","label":"2"}],"html":"<p>1 גרם וסיבוב causing  ב״ק כ״א ע״ב: הכשרתי במקצת נזקו וכו׳ כהכשר כל נזקו.\n2 סיגול דבר (לקבל טומאה) cause of fitness  זבח׳ ק״ח ע״א: הכשר טומאה.</p>","notation":["ז׳"]},"36853":{"h":"הֶכְשֵׁרוּת","r":"KRU05880","alt":[],"source":"krupnik","glosses":[{"text":"charity","label":""}],"html":"<p>חסד ונדיבות charity  מכי׳ בוא סוף פט״ז: שנהג עמהם בהכשרות.</p>","notation":["נ׳"]},"36854":{"h":"הַלְבְּשׁוּשׁ","r":"KRU05882","alt":[],"source":"krupnik","glosses":[{"text":"sore","label":""}],"html":"<p>פצע וחבורה sore  תרג׳ תה׳ כ״ב י״ח (עצמותי): הלבשושי גרמיי.</p>","notation":["ז׳"]},"36855":{"h":"הַלָּה","r":"KRU05883","alt":[],"source":"krupnik","glosses":[{"text":"that one there","label":""}],"html":"<p>ההוא that one there  כת׳ פי״ג מ״ח: המוציא שטר חוב על חברו והלה מוציא שמכר לו את השדה.</p>","notation":["מה״ג"]},"36856":{"h":"הַלְוָאָה","r":"KRU05884","alt":[],"source":"krupnik","glosses":[{"text":"loan","label":""}],"html":"<p>משה יד, מִלוה loan  ב״מ י״ד ע״א: שטר הלואה.</p>","notation":["נ׳"]},"36857":{"h":"הַלְוַאי","r":"KRU05885","alt":[],"source":"krupnik","glosses":[{"text":"oh that!","label":""}],"html":"<p>מי יתן oh that!  ב״ר פס״ג: אם כך הוא צערן של בנים הלואי לא עיברתי.</p>","notation":["מה״ח"]},"36858":{"h":"הַלְוָיָיה","r":"KRU05887","alt":[],"source":"krupnik","glosses":[{"text":"accompaniment","label":""}],"html":"<p>הליכה אחרי־ accompaniment  ירוש׳ סוטה פ״ט כ״ג ע״ד: ופטרנהו בלא הלוייה.</p>","notation":["נ׳"]},"36859":{"h":"הִלּוּךְ מֵעַיִם","r":"KRU05889","alt":[],"source":"krupnik","glosses":[{"text":"relaxation of the bowels","label":""}],"html":"<p>שלשול relaxation of the bowels  ב״ר פ״ר: הלוך מעים בדרך ארץ.</p>","notation":[]},"36860":{"h":"הִלּוּל","r":"KRU05890","alt":[],"source":"krupnik","glosses":[{"text":"recitation of Hallel","label":""}],"html":"<p>אמירת הלל recitation of Hallel  במ״ר פ״ג: לולב להילול.</p>","notation":["ז׳"]},"36861":{"h":"הֲלָזָה","r":"KRU05892","alt":[],"source":"krupnik","glosses":[{"text":"talk, sneer","label":""}],"html":"<p>לעז, שמועה talk, sneer  תוס׳ כת׳ ב׳ ג׳: ונפלה הלזה בעיר.</p>","notation":["נ׳"]},"36862":{"h":"הָלֵין","r":"KRU05894","alt":[],"source":"krupnik","glosses":[{"text":"these, those","label":""}],"html":"<p>הללו these, those  נדר׳ ע״ט ע״ב: הלין והלין.</p>","notation":["מה״ג"]},"36863":{"h":"הִלֵּךְ","r":"KRU05895","alt":[],"source":"krupnik","glosses":[{"text":"to cause opening of the bowels","label":""}],"html":"<p>פיעל,·– גרם שלשול to cause opening of the bowels  ירוש׳ כלא׳ פ״א כ״ז ע״א: ומהלכת את בני מעים.</p>","notation":[]},"36864":{"h":"הַלְכָא","r":"KRU05896","alt":[],"source":"krupnik","glosses":[{"text":"hither","label":""}],"html":"<p>לכאן hither  תרג׳ שמ׳ ג׳ ה׳ (הלום): הלכא.</p>","notation":["תה״פ"]},"36865":{"h":"הֲלָכָה","r":"KRU05897","alt":[],"source":"krupnik","glosses":[{"text":"rule, tradional law","label":"1"},{"text":"Halachha, the legislative part of the Talmud","label":"2"}],"html":"<p>1 חוק rule, tradional law  אבות פ״ו מ״ג: הלומד מחבירו פרק אחד או הלכה אחת.\n2 חלק החוקים שבתלמוד בנגוד לחלק האגדה Halachha, the legislative part of the Talmud  נדר׳ פ״ד מ״ג: מדרש הלכות והגדות.</p>","notation":["נ׳"]},"36866":{"h":"הִלְכָךְ","r":"KRU05898","alt":[],"source":"krupnik","glosses":[{"text":"therefore","label":""}],"html":"<p>על כן, לפיכך therefore  תענ ג׳ ע״ב: הלכך בימות החמה אמר משיב הרוח אין מחזירין אותו.</p>","notation":["מה״ח"]},"36867":{"h":"הִלֵּל","r":"KRU05901","alt":[],"source":"krupnik","glosses":[{"text":"name of Tannaim and Amoraim","label":""}],"html":"<p>שם תנאים ואמוראים name of Tannaim and Amoraim  יומא ל״ה ע״ב: הלל מחייב את העניים. ועי׳ הִילֵל.</p>","notation":[]},"36868":{"h":"הַלֵּל","r":"KRU05902","alt":["הַלֵּלָא"],"source":"krupnik","glosses":[{"text":"recitations for Holy Day, consisting of Ps. CXIII to CXVIII","label":""}],"html":"<p>מזמורים קי״ג–קי״ח בתהלים, הנאמרים בימים טובים recitations for Holy Day, consisting of Ps. CXIII to CXVIII  תענ׳ כ״ח ע״ב: י״ח יום בשנה יחיד גומר בהן את ההלל; מגי׳ י״ד ע״א: קרייתא זו הללא.</p>","notation":[]},"36869":{"h":"הַלָּלוּ","r":"KRU05903","alt":[],"source":"krupnik","glosses":[{"text":"those","label":""}],"html":"<p>אלה, אותם those  עיר׳ נ״ד ע״א: הללו נוצצין והללו נובלין.</p>","notation":["מה״ג"]},"36870":{"h":"הָלַם","r":"KRU05905","alt":[],"source":"krupnik","glosses":[{"text":"to fit","label":""}],"html":"<p>·– התאים to fit  ע״ז מ״ד ע״א: שכל הראוי למלכות הולמתו (העטרה) וכל שאינו ראוי למלכות אין הולמתו.</p>","notation":[]},"36871":{"h":"הֶהֱלִים","r":"KRU05906","alt":[],"source":"krupnik","glosses":[{"text":"to paste on","label":""}],"html":"<p>הפע׳, דיבק to paste on  ירוש׳ תרו׳ י׳ מ״ז ע״א: מהלימין היו.</p>","notation":[]},"36872":{"h":"הַלָּן","r":"KRU05907","alt":[],"source":"krupnik","glosses":[{"text":"there","label":""}],"html":"<p>שם there  ירוש׳ כת׳ פ״ד כ״ח ע״ד: בני בנים שכאן הוא בני בנים של הלן.</p>","notation":["תה״פ"]},"36873":{"h":"הֲלָנָה","r":"KRU05908","alt":[],"source":"krupnik","glosses":[{"text":"reserving for the next morning, undue delay over night","label":"1"},{"text":"murmuring","label":"2"}],"html":"<p>1 השארה למחר reserving for the next morning, undue delay over night  סנה׳ ל״ד ע״א: הלנת דין.\n2 תרעומת murmuring  שמו״ר פכ״ה: מה הלנה היה שם וכו׳ ושלם אותו הבצק ובערב הלינו.</p>","notation":["נ׳"]},"36874":{"h":"הַלְעָטָה","r":"KRU05909","alt":[],"source":"krupnik","glosses":[{"text":"stuffing","label":""}],"html":"<p>פיטום stuffing  תוס׳ שבת י״ח ג׳: ואיזו היא הלעטה כל שמאכילו מעומד ומשקהו מעומד וכו׳.</p>","notation":["נ׳"]},"36875":{"h":"הִלְקֵט","r":"KRU05910","alt":[],"source":"krupnik","glosses":[{"text":"to stuff","label":"1"}],"html":"<p>1 הלעיט, פיטם to stuff  שבת פכ״ד מ״ג: מלעיטין וממרין לתרנגולין.\n2 עי׳ לְקַט. </p>","notation":["פ״י"]},"36876":{"h":"הַלְקָשָׁה","r":"KRU05911","alt":[],"source":"krupnik","glosses":[{"text":"doing late","label":""}],"html":"<p>איחור doing late  במ״ר פכ״ג: שמא אמרתי להכניס אתכם לארץ והלקשתי אתכם וכו׳ לשון הלקשה.</p>","notation":["נ׳"]},"36877":{"h":"הַמְדַּאי","r":"KRU05914","alt":["הַמְדַּיי"],"source":"krupnik","glosses":[{"text":"Media","label":""}],"html":"<p>ארץ מדי Media  תרג׳ דהי״א א׳ ה׳ (ומדי): והמדאי; תרג׳ יב״ע בר׳ י׳ ב׳: והמדיי.</p>","notation":[]},"36878":{"h":"הָמָה","r":"KRU05915","alt":[],"source":"krupnik","glosses":[{"text":"to covet","label":"הִמָּה פיעל"}],"html":"<p>הִמָּה פיעל היה בהול אחרי־ to covet  קה״ר ה׳ ט׳: ומהמה אחר הממון.</p>","notation":["Source marks no qal form"]},"36879":{"h":"הִמוֹנְיָיא","r":"KRU05916","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>שם מקום name of a place  שהש״ר ה׳ י״ד: למזבון עיבור מן קרייתא המונייא.</p>","notation":[]},"36880":{"h":"הֵמְטַלְיָא","r":"KRU05917","alt":[],"source":"krupnik","glosses":[{"text":"liver-wort","label":""}],"html":"<p>מין צמח liver-wort  ע״ז ל״ח ע״ב: המטליא.</p>","notation":["נ׳"]},"36881":{"h":"הֵמְיוֹנָס","r":"KRU05918","alt":[],"source":"krupnik","glosses":[{"text":"mule","label":""}],"html":"<p>פרד mule  ירוש׳ בר׳ פ״ח י״ב: היֵמם – המיונס.</p>","notation":["ז׳"]},"36882":{"h":"הֶמְיָין","r":"KRU05919","alt":["הִמְיָינָא"],"source":"krupnik","glosses":[{"text":"belt, girdle","label":""}],"html":"<p>אזור belt, girdle  סוכה פ״ה מ״ג: ומהמייניהן היו מפקיעין וכו׳; זבח׳ י״ט ע״א: הוא מדלי המיינאי.</p>","notation":[]},"36883":{"h":"הֲמִים","r":"KRU05921","alt":[],"source":"krupnik","glosses":[{"text":"melancholic, confused in mind","label":""}],"html":"<p>עצוב ונוגה melancholic, confused in mind  ירוש׳ תר׳ א׳ מ׳ ע״ב: מהו קורדייקוס אמר רב המים.</p>","notation":["ת׳"]},"36884":{"h":"הֵמִינָא","r":"KRU05922","alt":[],"source":"krupnik","glosses":[{"text":"a liquid measure","label":""}],"html":"<p>מין מדת הלח a liquid measure  תרג׳ שני אס׳ א׳ ח׳: ארבע חמשא המינין.</p>","notation":["ז׳"]},"36885":{"h":"הִמִיסוּ","r":"KRU05923","alt":[],"source":"krupnik","glosses":[{"text":"mule","label":""}],"html":"<p>פרד mule  ב״ר סוף פפ״ב: היֵמם – המיסו.</p>","notation":["ז׳"]},"36886":{"h":"הֲמִירוֹס","r":"KRU05924","alt":["הֲמִירָם"],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ידים פ״ד מ״ו: ספרי המירם אינם מטמאים את הידים; ירוש׳ סנה׳ פ״י כ״ח ע״א: ספרי המירוס. </p>","notation":[]},"36887":{"h":"הָמַם","r":"KRU05926","alt":[],"source":"krupnik","glosses":[{"text":"to sweep","label":""},{"text":"to mutilate one’s self","label":""}],"html":"<p>טאטא to sweep  איכ״ר פתיחתא (ר׳ אבהו ב׳): הממם כבמכביד. אִתְהָמֵם אתפ׳ עשה שרטת to mutilate one’s self  תרג׳ מל״א י״ח (ויתגודדו): ואתהממו. </p>","notation":["Marked biblical in source"]},"36888":{"h":"הֲמָמָא","r":"KRU05927","alt":[],"source":"krupnik","glosses":[{"text":"sweepings","label":""}],"html":"<p>פסולת sweepings  תרג׳ עמ׳ ח׳ ו׳ (ומפל בר): והממת עיבורא.</p>","notation":["ז׳"]},"36889":{"h":"הֲמָמָה","r":"KRU05928","alt":[],"source":"krupnik","glosses":[{"text":"pestilence","label":""}],"html":"<p>דֶבר pestilence  מכי׳ בשלח פ״ה: אין הממה אלא מגפה.</p>","notation":["נ׳"]},"36890":{"h":"הַמְנוּנָא","r":"KRU05930","alt":[],"source":"krupnik","glosses":[{"text":"name of Amoraim","label":""}],"html":"<p>שם אמוראים name of Amoraim  ירוש׳ תענ׳ פ״ד ס״ח ע״א: רב המנונא דבבל.</p>","notation":[]},"36891":{"h":"הַמְנֵיק","r":"KRU05931","alt":[],"source":"krupnik","glosses":[{"text":"fork","label":""}],"html":"<p>מזלג fork  ב״מ כ״ה ע״ב: סכיני והמניק.</p>","notation":["ז׳"]},"36892":{"h":"הֶמְסֵס","r":"KRU05934","alt":["הֶמְסֵסָא"],"source":"krupnik","glosses":[{"text":"psalterium (anat.)","label":""}],"html":"<p>קיבה שלישית של מעלי גרה psalterium (anat.)  חול׳ פ״ג מ״א: המסס ובית הכוסות; ילק׳ קהל׳ תתקע״ו: המססא.</p>","notation":[]},"36893":{"h":"הַמְעָסָה","r":"KRU05935","alt":[],"source":"krupnik","glosses":[{"text":"stirring of dough","label":""}],"html":"<p>גיבול עיסה stirring of dough  פס׳ ל״ז ע״א: המעסה קמח על גבי מי גלשים.</p>","notation":["נ׳"]},"36894":{"h":"הַמְצָיָה","r":"KRU05936","alt":[],"source":"krupnik","glosses":[{"text":"pressing out","label":""}],"html":"<p>סחיטה pressing out  ספרא א׳ ח׳: מה הקטרה למעלן אף המציה למעלן.</p>","notation":["נ׳"]},"36895":{"h":"הַמְרָאָה","r":"KRU05937","alt":[],"source":"krupnik","glosses":[{"text":"stuffing (pushing far down the gullet)","label":"1"},{"text":"rebellion","label":"2"}],"html":"<p>1 הלעטה stuffing (pushing far down the gullet)  שבת קנ״ה ע״ב: והמראה בכלי הלעטה ביד.\n2 מרי, מרד rebellion  סנה׳ י״ד ע״ב: יכול תהא המראתי המראה.</p>","notation":["נ׳"]},"36896":{"h":"הֲמָרָה","r":"KRU05938","alt":[],"source":"krupnik","glosses":[{"text":"change of religion, apostasy","label":""}],"html":"<p>הֲמָרַת דָּת חילוף דת, שמד change of religion, apostasy  פסח׳ צ״ו ע״א: ואין המרת דת פוסלת בתרומה.</p>","notation":["נ׳"]},"36897":{"h":"הַמְרָכָה","r":"KRU05940","alt":[],"source":"krupnik","glosses":[{"text":"softening","label":""}],"html":"<p>התמזמזות softening  חול׳ מ״ה ע״ב: המרכה כל שנשפך כקיתון.</p>","notation":["נ׳"]},"36898":{"h":"הַמְשָׁכָה","r":"KRU05941","alt":[],"source":"krupnik","glosses":[{"text":"conducting (water)","label":""}],"html":"<p>העברת מים conducting (water)  תמורה י״ב ע״ב: שהשאיבה מטהרת ברבייה ובהמשכה.</p>","notation":["נ׳"]},"36899":{"h":"הָן","r":"KRU05943","alt":[],"source":"krupnik","glosses":[{"text":"this one, that one","label":"1"},{"text":"here","label":"2"}],"html":"<p>1 זה, ההוא this one, that one  ירוש׳ כלא׳ פ״ט ל״ג: הן שאל להן והן שאל להן.\n2 מה״י, כאן here  ירוש׳ נדר׳ פ״ו מ׳ ע״א: הן דמטא מטא הן דלא מטא וכו׳.</p>","notation":["מה״ג"]},"36900":{"h":"הֲנָאָה","r":"KRU05944","alt":[],"source":"krupnik","glosses":[{"text":"pleasure, benefit","label":"1"},{"text":"objection","label":"2"}],"html":"<p>1 עונג, תועלת pleasure, benefit  סנה׳ פ״ח מ״ה: שמיתתן של רשעים הנאה להם והנאה לעולם.\n2 הפרעה והפרה objection  ספרי מטות קנ״ג: ואם הניא אביה אותה איני יודע הנאה זו מה היא וכו׳ הנאה זו הפרה.</p>","notation":["ז׳"]},"36901":{"h":"הִנְדְּוָאָה","r":"KRU05945","alt":[],"source":"krupnik","glosses":[{"text":"Indian","label":""}],"html":"<p>מארץ הודו Indian  ע״ז ט״ז ע״א: פרזלא הנדואה.</p>","notation":["ת׳"]},"36902":{"h":"הִנְדְּוִין","r":"KRU05946","alt":[],"source":"krupnik","glosses":[{"text":"Indian vestments","label":""}],"html":"<p>בגדים הודיים Indian vestments  יומא ל״ד ע״ב: הנדוין של ת״ת זוז.</p>","notation":["ז״ר"]},"36903":{"h":"הנדז","r":"KRU05947","alt":[],"source":"krupnik","glosses":[{"text":"to coincide","label":"אִיהַנְדֵז אתפ׳"}],"html":"<p>אִיהַנְדֵז אתפ׳ היה מכוון זה כנגד זה to coincide  חול׳ מ״ג ע״א: זמנין דמיהנדזי בהדי הדדי.</p>","notation":["Source marks no qal form"]},"36904":{"h":"הִנְדִּי","r":"KRU05948","alt":[],"source":"krupnik","glosses":[{"text":"Indian","label":""}],"html":"<p>הודי Indian  מדרש תה׳ ו׳: חרב הנדית.</p>","notation":["ת׳"]},"36905":{"h":"הֶנְדְּיוֹס","r":"KRU05949","alt":[],"source":"krupnik","glosses":[{"text":"wrestler","label":""}],"html":"<p>מתגושש wrestler  מדר׳ תהל׳ ט״ז י״א: שני הנדיוסין באין.</p>","notation":["ז׳"]},"36906":{"h":"הִנְדִּיקִי","r":"KRU05950","alt":[],"source":"krupnik","glosses":[{"text":"India","label":""}],"html":"<p>ארץ הודו India  קה״ר ב׳ ו׳: ושולח להנדיקי.</p>","notation":[]},"36907":{"h":"הִנְדֵּס","r":"KRU05951","alt":[],"source":"krupnik","glosses":[{"text":"to gauge","label":""}],"html":"<p>בדק את המדות והמשקלים to gauge  ב״ב פ״ט ע״ב: באתרא דלא מהנדסי.</p>","notation":["פ״י"]},"36908":{"h":"הִנְדְּקוֹקֵי","r":"KRU05953","alt":[],"source":"krupnik","glosses":[{"text":"lucerne","label":""}],"html":"<p>מין אספסת lucerne  עיר׳ כ״ח ע״א: הנדקוקי מדאי.</p>","notation":["ז״ר"]},"36909":{"h":"הנה","r":"KRU05954","alt":[],"source":"krupnik","glosses":[{"text":"to enjoy, to profit","label":"נֶהֱנֶה נפ׳"}],"html":"<p>נֶהֱנֶה נפ׳ קבל הנאה ותועלת to enjoy, to profit  ב״ק כ׳ ע״א: זה נהנה וזה חסר.</p>","notation":["Source marks no qal form"]},"36910":{"h":"הִנָּה","r":"KRU05955","alt":[],"source":"krupnik","glosses":[{"text":"to benefit, to cause to share","label":""}],"html":"<p>פיעל, הֶהֱנָה הפ׳, גרם הנאה to benefit, to cause to share  בר׳ ס״ג ע״ב: ומאכילו ומשקהו ומהנהו מנכסיו; סנה׳ ק״ב ע״ב: ומתוך שההנה תלמידי חכמים וכו׳.</p>","notation":[]},"36911":{"h":"הַנָּה","r":"KRU05956","alt":[],"source":"krupnik","glosses":[{"text":"this","label":""}],"html":"<p>זה, זאת this  ב״ר פפ״ז: הנה טבא.</p>","notation":["מה״ג"]}};
